// Spanish (Latin American, tú) content for job group 09 (Sales / Customer Success (Ventas / Atención al cliente)). Keyed '09_<code>'.
// Used when the site language is Spanish. Korean remains in v2_data.js. There is no English pack for this job group.
window.ES_JOB = window.ES_JOB || {};
(function () {
  function T(name, type, tagline, guide, prompt) { return { name: name, type: type, tagline: tagline, daily_guide: guide, prompt_example: prompt }; }
  function add(code, title, main, spec, o) {
    window.ES_JOB['09_' + code] = {
      title: title,
      mainAI: { name: main, reason: '' },
      specialistAIs: spec.map(function (n) { return { name: n, reason: '' }; }),
      insight: o.i,
      v2: { insight_v2: o.i, strengths: o.s, growth_points: o.g, ai_tools: o.t, synergy_strategy: o.syn, daily_routine: o.day }
    };
  }
  add('00000', 'El vendedor independiente que rinde en silencio, sin alboroto', 'Claude', ['HubSpot AI', 'ChatGPT'], {
    i: 'Tu forma de vender no es llamativa. Cumples lo que prometiste, contactas cuando hace falta y, si aparece un problema, lo resuelves en silencio. Esta combinación, con apertura, responsabilidad, extraversión, amabilidad y neuroticismo todos bajos (20-27%), es, en el área de ventas, la del “vendedor independiente que produce un resultado constante, sin alboroto”. Tu forma no es una red amplia ni una presentación brillante: es una venta callada, basada en la confianza de uno a uno. En un mercado de competencia intensa, tú eres quien arma una base constante, que no desaparece.',
    s: [
      'Una gestión consistente del cliente, sin emoción: en cualquier situación atiendes al cliente de forma estable. Aunque el cliente a tu cargo sea exigente, o el mercado esté difícil, no te tambaleas y cumples tu rol.',
      'Poca generación de conflicto: no creas un conflicto ni con un cliente, ni con un colega, ni con un competidor. Mantener un entorno de trato estable, a largo plazo, evita la salida de un cliente.',
      'Una capacidad de ejecución independiente: sin que te gestionen ni te indiquen, sabes tu rol y lo cumples en silencio. Eres el tipo de compañero en el que más puede confiar un manager de ventas.'
    ],
    g: [
      'Visibilizar tu presencia y tu actividad: si trabajas en silencio, sales perjudicado en una evaluación. Solo con el hábito de compartir con tu líder, una vez a la semana, un resumen de tu actividad, cambia la velocidad con la que te reconocen.',
      'Fijar un mínimo de captación de clientes nuevos: como todas las dimensiones son bajas, si te concentras solo en la gestión de los clientes actuales, el pipeline se puede reducir. Fija como mínimo 2 contactos nuevos o más a la semana.'
    ],
    t: [T('Claude', 'main', 'El socio callado de todo el trabajo de ventas', 'Claude es el socio de todo el trabajo de ventas que resuelves tú solo. El borrador de una propuesta, un correo a un cliente, un escrito de respuesta a un reclamo, un aviso de renovación de un contrato: con Claude solo se resuelve la mayor parte. Lo que te resulta incómodo preguntarle a un colega, pregúntaselo con comodidad a Claude.', 'Claude, el cliente a mi cargo presentó un reclamo por un atraso de entrega. La causa del atraso es un problema de un socio, pero, por contrato, la responsabilidad es nuestra. Escribe una respuesta oficial que reconozca el hecho y, a la vez, proteja al máximo la relación y deje abierta la siguiente transacción.'),
        T('HubSpot AI', 'specialist', 'El seguimiento automático de la actividad de ventas y los recordatorios', 'HubSpot AI rastrea en automático el seguimiento de los clientes que gestionas y te envía un aviso. A ti, que por una responsabilidad baja tiendes a dejar el follow-up para después, HubSpot te evita perder el momento.', 'HubSpot AI, resume mi actividad de ventas de este mes (reuniones, correos, llamadas). Ordena también, por cliente, la fecha del último contacto y la siguiente acción prevista.'),
        T('ChatGPT', 'specialist', 'Una propuesta rápida y una lectura de la información del mercado', 'ChatGPT es la herramienta con la que encuentras una respuesta con rapidez cuando un cliente hace una pregunta o una petición inesperada. Cuando, por una apertura baja, te cuesta explorar algo nuevo, ChatGPT te ordena lo esencial con rapidez.', 'ChatGPT, mañana parece que el cliente va a preguntar una comparación con el producto del competidor A. Ordena de forma breve 5 fortalezas principales de nuestro producto y los puntos de diferenciación frente al competidor, desde el ángulo del precio, la calidad, el servicio, el plazo de entrega y el soporte técnico.')],
    syn: 'Tú, que te mueves de forma independiente y en silencio, con todas las dimensiones bajas, eres la base más estable de una organización de ventas. Si resuelves todo el trabajo con Claude, rastreas al cliente con HubSpot AI y, solo cuando hace falta, te preparas con rapidez con ChatGPT, te conviertes en el vendedor de confianza que produce un resultado constante, sin alboroto.',
    day: '09:00 Revisas con HubSpot AI la lista de clientes a los que contactar hoy. 09:30 Escribes con Claude el borrador del correo o del escrito que vas a enviar hoy. 10:30 Contacto y reuniones con clientes. 13:30 Registras con HubSpot AI la actividad de la mañana. 14:30 Preparas con ChatGPT la respuesta a una pregunta que salió en una reunión. 16:00 Envío del correo de seguimiento. 17:00 Revisas con HubSpot AI el estado de la actividad de esta semana. 17:30 Preparación de mañana.'
  });
  add('00001', 'El tipo práctico y cool: el analista de ventas basado en hechos', 'Perplexity', ['YouTube AI (resumen)', 'BlackLine'], {
    i: 'Eres el pragmático frío del mundo de las ventas. La combinación de una apertura y una responsabilidad bajas, una extraversión y una amabilidad bajas, y un neuroticismo alto produce al especialista en ventas que, sin emoción, calcula solo el margen y cuida el resultado práctico como nadie. Ni la presión de un resultado de un superior, ni la embestida emocional de un cliente, te tambalean: decides solo sobre la base del hecho que muestran los números. La combinación de una extraversión y una amabilidad bajas te lleva a concentrarte, en lugar de una red amplia de clientes, en un número reducido de tratos de alta rentabilidad. Eso a veces puede parecer falta de capacidad de venta, pero, en realidad, es la forma de vender con la eficiencia de energía más alta. El margen de los contratos que tú cierras supera con mucho el promedio del equipo. El neuroticismo alto te da, junto con la inquietud por el resultado de una venta, una capacidad aguda de detectar un riesgo. Tu forma de rastrear con Perplexity la política de precios de un competidor, de aprender con eficiencia una tendencia reciente de ventas con el resumen de IA de YouTube, y de analizar con precisión la rentabilidad con BlackLine, maximiza el ROI de una venta basada en datos.',
    s: [
      'Una capacidad fría de decisión en ventas, que no se deja llevar por la emoción ni por la relación y pone en primer lugar el margen y la rentabilidad.',
      'Una capacidad de análisis del mercado que rastrea de forma continua la tendencia de precios de un competidor y el cambio del mercado, y arma la estrategia óptima de negociación de precios.',
      'Una capacidad pragmática de ejecución que, incluso en una recesión, se concentra en un trato de rentabilidad verificada y mantiene de forma estable el margen de beneficio de ventas de todo el equipo.'
    ],
    g: [
      'Como un neuroticismo alto puede hacerte estresar en exceso ante la incertidumbre de una venta, cultiva un enfoque de concentrarte en un indicador de actividad que sí puedes controlar, y de reducir la preocupación por un indicador de resultado.',
      'Como una amabilidad y una extraversión bajas pueden debilitar la formación de una relación de largo plazo con un cliente, incluye en la agenda una comunicación, cada trimestre, de mantenimiento de la relación con un cliente actual de alta rentabilidad.'
    ],
    t: [T('Perplexity', 'main', 'Captas de inmediato, con fuentes objetivas, la política de precios de un competidor', 'Captura de inmediato, junto con una fuente objetiva, la política de precios de un competidor, una estrategia de descuento y el cambio de las tarifas del mercado. Con una investigación rigurosa del mercado, antes de una negociación de precios, refuerzas tu posición de negociación y aseguras el mejor margen.', 'Resúmeme, con fuentes, la política de precios, la estrategia de descuento y el cambio de las tarifas del mercado de nuestros 3 competidores principales de este mes. Voy a negociar el precio mañana y quiero reforzar mi posición y asegurar el mejor margen.'),
        T('YouTube AI (resumen)', 'specialist', 'Aprende con eficiencia, en un resumen de IA, una estrategia de ventas y una técnica de negociación', 'Aprende con eficiencia, con un resumen de IA, un video sobre estrategia de ventas, técnica de negociación o gestión de precios. Extrae solo lo esencial de un contenido largo de formación, obtén el máximo de hallazgos en el mínimo de tiempo y actualiza de forma continua tu especialidad en ventas.', 'Resume en 10 minutos los puntos clave de este video sobre estrategia de negociación y gestión de precios, y dime qué puedo aplicar mañana en una negociación real.'),
        T('BlackLine', 'specialist', 'Analiza con precisión la rentabilidad por venta y el margen por cliente', 'Analiza con precisión la rentabilidad por venta, el margen por cliente y el impacto de un descuento. Identifica con datos a qué cliente debes concentrarte para maximizar el beneficio real, y asignar de forma óptima tu energía de ventas.', 'Analiza la rentabilidad por venta, el margen por cliente y el impacto de los descuentos de este mes. Dime a qué clientes debo concentrarme para maximizar el beneficio real, y cómo redistribuir la energía de ventas del equipo.')],
    syn: 'El socio con el que más sinergia tienes es un responsable de ventas extravertido, fuerte en formar una relación con el cliente y en la comunicación externa. La división de roles en la que ellos construyen la relación con el cliente y tú te encargas del análisis de rentabilidad y de la estrategia de negociación sube, al mismo tiempo, el resultado de ventas y la rentabilidad del equipo. Identifica, sobre la base de los datos de BlackLine, el segmento de clientes de alta rentabilidad, y propone la estrategia de concentrar en ese segmento el recurso de ventas de todo el equipo.',
    day: 'A las 7:30 de la mañana, captas con Perplexity la tendencia de precios del sector y el estado de un competidor del cliente con el que vas a negociar hoy. Fijas con claridad la línea roja de la negociación y el margen objetivo. A las 9:00 revisas con BlackLine la rentabilidad por venta de este mes. Identificas qué trato trae el margen más alto y decides el objetivo de concentración de hoy. A media mañana llevas la reunión de negociación con un cliente clave. Negocias con datos, más que con emoción. En el almuerzo, en 10 minutos, aprendes con el resumen de IA de YouTube un contenido de negociación o de ventas. Por la tarde registras en BlackLine el resultado de la negociación de la mañana y actualizas la siguiente estrategia de negociación. Antes de irte, revisas en conjunto la rentabilidad de las ventas de esta semana y armas la estrategia de la semana que viene.'
  });
  add('00010', 'El vendedor callado que construye confianza escuchando más que hablando', 'Claude', ['Notion AI', 'Otter.ai'], {
    i: 'En una reunión de ventas no hablas mucho. Cuando el cliente suelta un problema, escuchas en silencio y, después, dices una sola frase que da exactamente en el centro: “entonces, al final, el problema es este, ¿verdad? Tenemos un caso en el que resolvimos precisamente eso.” Tú, en quien se combinan una capacidad profunda de empatía, con un 82% de amabilidad, y una extraversión baja (22%), eres, en el área de ventas, “el vendedor callado que construye confianza escuchando más que hablando”. Con una apertura baja (25%) prefieres una forma estable y, con una responsabilidad también baja (27%), te acercas más por intuición que por un sistema. Con un neuroticismo bajo (18%), te mantienes sereno ante cualquier presión de una negociación.',
    s: [
      'Una venta de confianza basada en la escucha: con una amabilidad alta, captas la necesidad real que el cliente no llegó a decir. El contrato se cierra en el momento en que el cliente siente “esta persona de verdad entiende mi situación”.',
      'Una capacidad natural de mantener una relación de largo plazo: como la amabilidad es alta, eres de quienes reciben un contacto incluso cuando el cliente se cambia de empresa. La confianza humana dura más que la relación de negocio.',
      'Crear un entorno de venta cómodo, sin presión: una forma de vender callada, sin presión, abre más bien el ánimo de un cliente al que le cuesta decidir. La impresión de “con esta persona se trabajaría con comodidad” es la que lleva el contrato.'
    ],
    g: [
      'La capacidad de proponer con iniciativa: con una amabilidad alta y una extraversión baja, eres excepcional escuchando al cliente, pero se te puede hacer difícil proponer primero o cerrar. Te ayuda preparar de antemano un escenario de cierre del tipo “si el cliente dice esto, yo propongo esto”.',
      'La gestión del volumen de actividad: con una extraversión baja, el volumen de captación de clientes nuevos puede quedar corto. Fija un mínimo semanal de contactos nuevos (por ejemplo, 5) y rastréalo con HubSpot.'
    ],
    t: [T('Claude', 'main', 'Convierte lo que escuchaste en una propuesta convincente', 'Claude te ayuda, a ti que escuchas bien al cliente, a convertir esa información en la propuesta óptima. Si le cargas a Claude la preocupación y la necesidad que el cliente dijo en la reunión, se ordenan “el ángulo de la propuesta y el mensaje central que encajan con este cliente”. Se completa el ciclo de ventas más natural: de la escucha a la propuesta.', 'Claude, lo que escuché hoy en la reunión con el cliente: ahora les toma 10 horas a la semana ordenar datos a mano, hay un 5% de tasa de error, y 3 personas del equipo están agotadas por un trabajo repetido. Arma la línea argumental más convincente y el cálculo de ROI para proponerle a este cliente nuestra solución de automatización.'),
        T('Notion AI', 'specialist', 'La gestión del registro de una conversación con el cliente y del historial de la relación', 'Notion AI registra y gestiona de forma sistemática el contenido valioso de las conversaciones que tuviste con un cliente. Aunque, por una responsabilidad baja, tiendes a dejar el registro para después, si dejas solo una nota de 3 líneas justo después de la reunión, la IA más tarde te ordena todo el flujo.', 'Notion AI, en las notas de reuniones con clientes que he registrado hasta ahora, analiza el rasgo de la conversación inicial de los clientes que llegaron a un contrato de largo plazo (3 años o más). Encuentra el patrón de qué temas salieron con frecuencia en la primera reunión y de qué forma se formó la confianza.'),
        T('Otter.ai', 'specialist', 'Con el registro automático de la reunión, concéntrate en la escucha', 'Otter.ai te ayuda a concentrarte por completo, en una reunión, en lo que dice el cliente, sin tomar notas. Como la conversación se graba y se resume en automático, puedes concentrar en el cliente los ojos y los oídos, en lugar del bolígrafo. Eso maximiza tu mayor fortaleza: “una escucha de verdad”.', 'Otter.ai, analiza las transcripciones de las 15 reuniones con clientes de este mes y saca el TOP 10 de palabras clave del problema del cliente más mencionadas. Ordena también en qué sector apareció con más frecuencia cada palabra clave.')],
    syn: 'Tu forma de vender, que construye confianza escuchando, es lenta, pero crea la relación que más dura. Si sistematizas la propuesta con Claude, la relación con Notion AI y la escucha con Otter.ai, tu empatía callada se convierte en la confianza de cliente más sólida del sector.',
    day: '09:00 Repasas con Notion AI la conversación anterior del cliente de la reunión de hoy. 10:00 Reunión con el cliente (registro automático de Otter.ai). 12:00 Conviertes con Claude el contenido de la reunión en la línea argumental de una propuesta. 13:30 Registras con Notion AI el contenido de la reunión y cargas la siguiente acción. 15:00 Contacto regular con un cliente nuevo (gestión del número objetivo de la semana). 16:30 Revisión del resumen de la reunión de Otter.ai. 17:30 Preparas con Claude la propuesta de la reunión de mañana.'
  });
  add('00011', 'El perezoso imperturbable del mostrador', 'Gemini', ['Spotify AI DJ', 'Zapier'], {
    i: 'Eres la fuerza invisible de paz de la tienda. La combinación de una apertura y una responsabilidad bajas, una extraversión baja y una amabilidad alta, y un neuroticismo alto, produce a un responsable de atención peculiar: te disgusta lo complejo, quieres vivir de forma simple y, aun así, reaccionas de verdad ante la incomodidad de un cliente. Tú, que, aunque te estreses por alcanzar el objetivo de un resultado, con tu calidez particular pareces haber llegado a un estado de desapego, en realidad te esfuerzas sin parar, por dentro, por mantener el equilibrio. Una amabilidad alta te lleva a tratar a todos los clientes con calidez, sin distinción. Incluso un cliente exigente se ablanda frente a ti. Esta afinidad natural crea al cliente habitual y se convierte en una fuerza de venta invisible que sigue en una recomendación de boca en boca. La combinación de una responsabilidad baja y un neuroticismo alto a veces provoca la preocupación de que se te escape una tarea. Automatiza con Gemini la gestión de la agenda y del inventario, mantén el ambiente del lugar con Spotify AI DJ y automatiza el trabajo repetido con Zapier, para reducir la preocupación y crear un entorno en el que te puedas concentrar en la comunicación con el cliente.',
    s: [
      'Una afinidad natural que recibe con calidez, y sin juzgar, a todo tipo de cliente, y deja cómodo incluso a uno exigente.',
      'La capacidad de armonizar un conflicto que, incluso en una crisis o en una queja, mantiene un ambiente de paz, suaviza el roce y tranquiliza a todas las partes.',
      'Un juicio práctico de terreno que resuelve de forma simple e intuitiva una situación compleja con un cliente.'
    ],
    g: [
      'Como una omisión de trabajo, por una responsabilidad baja, puede afectar la calidad del servicio al cliente, arma una rutina simple de revisar, cada mañana, 3 comprobaciones esenciales.',
      'Como un neuroticismo alto puede convertirse en la preocupación por un error de trabajo, reduce con herramientas de automatización la posibilidad de un error e invierte esa energía de preocupación en la comunicación con el cliente.'
    ],
    t: [T('Gemini', 'main', 'El asistente de IA que, si se lo pides en voz, resuelve en automático el inventario, la agenda y una reserva', 'Úsalo como un asistente de IA que, si se lo pides en voz, resuelve en automático la comprobación del inventario, la gestión de la agenda de la tienda y el trámite de una reserva de un cliente. Le delegas a Gemini el trabajo complejo de gestión y tú te concentras en la comunicación con el cliente.', 'Revisa el inventario de hoy, la agenda de la tienda y las reservas de clientes. Resume lo fuera de lo común y dime las 3 comprobaciones esenciales de esta mañana.'),
        T('Spotify AI DJ', 'specialist', 'La IA que cura, en automático, la música que encaja con el ambiente de la tienda', 'Configura que la IA cure en automático la música que encaja con el ambiente de la tienda. Al crear el ambiente adecuado por franja horaria y por tipo de cliente, subes el tiempo de permanencia y la satisfacción de compra.', 'Arma una lista para esta mañana en la tienda: un tono tranquilo y acogedor, que suba el tiempo de permanencia y la satisfacción de compra, y que hacia el mediodía pase a un ritmo un poco más vivo.'),
        T('Zapier', 'specialist', 'Automatiza el aviso de un pedido, el recordatorio de inventario y el mensaje de agradecimiento a un cliente habitual', 'Automatiza el trabajo repetido, como el aviso de un pedido, el recordatorio de comprobación de inventario o el mensaje de agradecimiento a un cliente habitual. Al automatizar la tarea administrativa que se te escapa con facilidad, te liberas de la preocupación de dejar pasar algo importante.', 'Automatiza estas 3 tareas administrativas que más se me escapan: el aviso de un pedido, el recordatorio de comprobación de inventario y el mensaje de agradecimiento a un cliente habitual.')],
    syn: 'El socio con el que más sinergia tienes es un colega minucioso, fuerte en una gestión sistemática del trabajo y en el análisis de un resultado. La división de roles es natural: ellos crean la estructura y el sistema, y tú, dentro de eso, armas una relación cálida con el cliente. Automatiza con Zapier las 3 tareas administrativas de la tienda que más se omiten, e invierte más tiempo en tu fortaleza natural: la comunicación con el cliente.',
    day: 'A las 8:30 de la mañana, con un aviso automático de Zapier, identificas el pedido y la comprobación de inventario que hay que resolver hoy. Le pides a Gemini que revise la agenda de la tienda de hoy y que ordene lo fuera de lo común. A las 9:00, al abrir la tienda, arrancas con Spotify AI DJ la lista que encaja con el ambiente de la mañana. A media mañana conversas de forma natural con un cliente que entra. Si aparece una situación difícil con un cliente, respondes con calma. En el almuerzo, revisas con Gemini el estado del inventario de la tarde y le indicas en voz la medida necesaria. Por la tarde priorizas la comunicación con los clientes habituales y revisas el mensaje de agradecimiento a un habitual que Zapier envía en automático. 15 minutos antes del cierre, con la lista de verificación de Zapier, confirmas si terminaste la tarea administrativa esencial de hoy.'
  });
  add('00100', 'Quien abre la cartera por instinto: el mustang del piso de ventas', 'Grok', ['Zapier', 'HeyGen'], {
    i: 'Eres el carisma de humor cambiante de la tienda. La combinación de una apertura y una responsabilidad bajas, una extraversión alta, una amabilidad baja y un neuroticismo bajo produce al vendedor fuera de lo común, que mueve al cliente más por el instinto que por el análisis, y más por el ímpetu que por un plan. Si hoy estás de buen humor, se anima toda la tienda, esa energía se le transmite al cliente y se produce el milagro de alcanzar antes el objetivo de ventas. La combinación de una extraversión alta y un neuroticismo bajo te da una resistencia fuerte de ventas: te pones, con energía, frente al cliente en cualquier situación, y te recuperas con facilidad incluso de un fracaso. Aunque te encuentres con un cliente difícil, te desconciertas, pero enseguida te sacudes el polvo y te concentras en el siguiente. Esta resiliencia produce un resultado sostenible incluso en un entorno de ventas de alta presión. Tú, que confías más en la intuición que en los datos, puedes pasarlo mal cuando hace falta una estrategia de ventas precisa, basada en la lógica. La forma de captar con rapidez una tendencia del mercado con Grok, de automatizar el trabajo repetido con Zapier para invertir más tiempo en el terreno de ventas, y de ampliar el canal digital de ventas con HeyGen, le suma datos a tu instinto.',
    s: [
      'Una presencia que, con un carisma natural y una energía abrumadora de terreno, estimula la psicología de compra del cliente y cierra un contrato grande.',
      'Una constancia que, con la resiliencia de sacudirte el polvo con rapidez ante cualquier fracaso, mantienes una actividad constante de ventas y, en una crisis, armas un vuelco dramático.',
      'Un sentido de ventas de terreno que, en la reacción del cliente, captas de forma intuitiva la señal de compra y pasas de inmediato al cierre.'
    ],
    g: [
      'Como una responsabilidad baja puede hacer que se descuide el registro de una venta y la gestión de un documento de contrato, fija el principio de “primero el documento, después la celebración”: un documento de un contrato importante se tramita en cuanto se termina.',
      'Como una venta centrada en la intuición puede no reaccionar con sensibilidad a un cambio del mercado, suma una rutina simple de investigación: una vez a la semana, revisa con Grok la tendencia del mercado.'
    ],
    t: [T('Grok', 'main', 'Captas con rapidez la tendencia del mercado y la palabra clave a la que reacciona el cliente', 'Captura con rapidez la tendencia actual del mercado y la palabra clave más reciente a la que reaccionan los clientes. Actualizas el discurso de ventas y la forma de proponer, a la altura de la tendencia, y encuentras el punto de ataque que aprovecha un punto débil del competidor.', 'Resume en 5 minutos la tendencia del mercado de hoy y las palabras clave a las que más están reaccionando los clientes. Propón también cómo actualizar mi discurso de ventas y 3 puntos de ataque que aprovechen un punto débil de un competidor.'),
        T('Zapier', 'specialist', 'Automatiza el seguimiento de después de un contrato, el agradecimiento al cliente y el recordatorio de un documento', 'Automatiza el trabajo repetido, como el seguimiento de después de un contrato, el envío de un mensaje de agradecimiento al cliente o el recordatorio de un documento. Haces que, mientras tú te concentras en la venta de terreno, la tarea importante se resuelva en automático.', 'Automatiza el seguimiento de después de un contrato de hoy, el mensaje de agradecimiento al cliente y el recordatorio de un documento pendiente, para que yo pueda concentrarme en la venta de terreno.'),
        T('HeyGen', 'specialist', 'Amplía tu carisma a un canal digital de ventas', 'Amplía tu carisma a un canal digital de ventas. Con un video de un avatar de IA, produces a gran escala una presentación de un producto y una propuesta a un cliente, y superas el límite de una venta presencial.', 'Arma el guion de un video corto de un avatar de IA que presente nuestro producto estrella y cierre con una propuesta al cliente, para publicarlo en un canal digital de ventas.')],
    syn: 'El socio con el que más sinergia tienes es un colega de perfil analítico, fuerte en la gestión sistemática de los datos de ventas y en el seguimiento. La división de roles en la que tú cierras un contrato grande en el terreno y ellos gestionan los datos y mantienen la relación maximiza el resultado de ventas del equipo. Comparte con regularidad en redes el video de ventas que produciste con HeyGen, para ampliar el canal de modo que tu carisma presencial también funcione en línea.',
    day: 'A las 8:00 de la mañana, captas en 5 minutos, con Grok, el tema y la tendencia del mercado de hoy. Anotas la palabra clave que vas a usar en la venta de hoy. A las 9:00, al abrir la tienda, recibes al cliente en un estado de alta energía. A media mañana te concentras al máximo en la venta de terreno y vuelcas toda la energía en un cliente con posibilidad de un contrato grande. En el almuerzo configuras con Zapier la automatización del seguimiento de un contrato de la mañana. Con HeyGen bosquejas la idea de un video nuevo de ventas. Por la tarde sigues vendiendo, manteniendo la energía de la mañana. Antes del cierre revisas la configuración de la automatización de Zapier y registras, de forma breve, el resultado de hoy.'
  });
  add('00101', 'El competidor impetuoso de la tienda, el mustang del terreno', 'Grok', ['CapCut AI', 'Beautiful.ai'], {
    i: 'Eres el mustang de la tienda. La combinación de una apertura y una responsabilidad bajas, una extraversión alta, una amabilidad baja y un neuroticismo alto produce al vendedor de instinto, que mueve al cliente más por el ímpetu que por un plan, más por la intuición que por el análisis, y más por una demostración que por una explicación. Una estrategia de venta compleja no es tu estilo. Tu forma es demostrar el producto en persona, frente al cliente, y llevar la decisión de compra con una energía potente. Una extraversión alta te da la capacidad de atraer, de forma natural, la mirada del cliente en el terreno y de transmitirle energía. Cuando entras tú, cambia el ambiente de la tienda. Esta presencia, para un cliente intuitivo, se convierte en una señal potente de compra. Un neuroticismo alto te hace reaccionar con sensibilidad a la variación del resultado de un día. Aunque hoy el resultado sea 0, tienes el optimismo de esperar el de mañana, pero, por dentro, se acumula la inquietud por un fracaso. Tu forma de captar con rapidez una tendencia con Grok, de producir un video de ventas de terreno con CapCut AI y de armar un material de propuesta de impacto con Beautiful.ai, le suma una herramienta digital a una venta instintiva.',
    s: [
      'Un carisma de ventas de terreno que, con una energía potente en el lugar y una demostración del producto, lleva de inmediato la decisión de compra del cliente.',
      'Una constancia optimista que, con la resiliencia de sacudirte el polvo enseguida ante cualquier fracaso, mantienes una actividad constante de ventas.',
      'Un sentido de terreno que, sensible a la tendencia, captas con rapidez el producto y el mensaje que más atención están recibiendo ahora en el mercado.'
    ],
    g: [
      'Como una responsabilidad baja puede hacer que se descuide el registro de una venta y el seguimiento, arma una rutina de, al final del día, automatizar el seguimiento de 3 clientes con los que contactaste hoy.',
      'Como una amabilidad baja te lleva a concentrarte más en un cierre de corto plazo que en formar una relación de largo plazo con el cliente, rastrea por separado la tasa de recompra de un cliente de largo plazo, con el que llevas más de 1 año de trato, y reconoce el valor de la relación.'
    ],
    t: [T('Grok', 'main', 'Captas en tiempo real la tendencia de consumo y el meme más candentes', 'Captura en tiempo real la tendencia de consumo y el meme más candentes ahora. Actualizas el discurso de ventas que le llega al cliente, a la altura de la tendencia más reciente, y captas con rapidez una reacción del mercado que el competidor se saltó.', 'Dime, en 5 minutos, la tendencia de consumo y el meme más candentes de hoy, y 3 frases de un discurso de ventas actualizado con las que se las pueda plantear a un cliente en la tienda.'),
        T('CapCut AI', 'specialist', 'Edita con rapidez un video de una demostración del producto en el terreno y un testimonio de un cliente', 'Edita con rapidez un video de una demostración del producto en el terreno y un contenido de testimonio de un cliente. Con la función de edición automática de la IA, minimizas el tiempo de producción de un video y armas un contenido de ventas de impacto, que atrae al cliente en redes.', 'Edita este video de la demostración del producto de esta mañana en un clip corto, de impacto, para redes, y añade un subtítulo que invite a un cliente potencial a la tienda.'),
        T('Beautiful.ai', 'specialist', 'Arma, en el momento, un material visual de comparación de un producto y una propuesta de ventas', 'Arma de forma visual el material de comparación de un producto y la propuesta de ventas que le vas a mostrar al cliente en el momento. Con un material de impacto, que combina datos e imágenes, llevas en el terreno la decisión del cliente.', 'Arma una propuesta visual de 5 diapositivas que compare nuestro producto con el de un competidor y que, en el terreno, le ayude al cliente a decidir en el momento.')],
    syn: 'El socio con el que más sinergia tienes es un colega de perfil analítico, fuerte en una gestión sistemática del cliente y en el análisis de datos. La división de roles es natural: tú creas el punto de contacto con un cliente nuevo en el terreno, y ellos sistematizan la relación con datos. Comparte con regularidad en redes el video de ventas de terreno que produciste con CapCut AI, para que la actividad presencial de ventas también llegue a un cliente potencial en línea.',
    day: 'A las 8:30 de la mañana, captas en 5 minutos, con Grok, la tendencia de consumo más reciente y el tema de hoy. Anotas la palabra clave de tendencia que vas a usar en la venta de hoy. A las 9:00, antes de abrir la tienda, terminas la preparación de la demostración del producto. Revisas en Beautiful.ai el material de propuesta que vas a usar hoy. A media mañana contactas con el mayor número posible de clientes y te concentras en la demostración del producto y en el cierre en el terreno. En el almuerzo editas con rapidez, con CapCut AI, el video del terreno de la mañana y lo compartes en redes. Por la tarde sigues vendiendo, con una energía todavía más alta que la de la mañana. 30 minutos antes del cierre, ordenas la lista de clientes con los que contactaste hoy y configuras la automatización del seguimiento.'
  });
  add('00110', 'El hermano o la hermana cálida del mercado, el rey de las ventas de buen corazón', 'ChatGPT', ['Mealime', 'Wysa'], {
    i: 'Eres el rey de las ventas de buen corazón del mercado. La combinación de una apertura y una responsabilidad bajas, una extraversión y una amabilidad altas, y un neuroticismo bajo produce al especialista cálido en ventas, que asegura al cliente habitual más con una comunicación de verdad que con una técnica llamativa de venta. Aunque el dueño te mire mal por dar de más, tu filosofía de ventas es hacer que los clientes hagan fila para verte la cara. La combinación de una amabilidad y una extraversión altas te da la capacidad natural de tratar a todos los clientes con comodidad y con calidez. Aunque un cliente se queje de que es caro, tú no te hieres y, al contrario, tienes la técnica psicológica de hacer que ese cliente vuelva y compre la siguiente vez. Gracias a un neuroticismo bajo, no reaccionas en exceso, a nivel emocional, ni ante la presión de una venta ni ante la queja de un cliente, y puedes responder con serenidad. Tu forma de escribir con ChatGPT un mensaje de gestión de un habitual y el texto de una promoción, de cuidar con Mealime la alimentación para gestionar el estrés de las ventas, y de mantener la salud emocional con Wysa, arma la base de una venta sostenible, centrada en el cliente.',
    s: [
      'Una afinidad natural que, con una comunicación de verdad, hace que incluso un cliente que acabas de conocer se sienta cómodo, compre o no, y lo invita a volver.',
      'Una serenidad que, ante la queja de cualquier cliente o una negociación de precio, no se altera a nivel emocional, responde con calidez y convierte una situación negativa en una positiva.',
      'Una capacidad de venta relacional que invierte en una relación de largo plazo con un cliente habitual y genera la entrada de un cliente nuevo a través de una recomendación de boca en boca.'
    ],
    g: [
      'Como una responsabilidad baja puede hacer que se descuide el registro de la gestión de un cliente habitual, arma, con ChatGPT y una herramienta de automatización, un sistema mínimo de gestión del cliente.',
      'Como una generosidad excesiva puede dañar el margen, fija con claridad el límite de un detalle y de un descuento, y arma la regla de dar lo mejor dentro de ese marco.'
    ],
    t: [T('ChatGPT', 'main', 'Escribe con calidez y atractivo el mensaje de agradecimiento, la promoción y la invitación a un habitual', 'Escribe con calidez y atractivo el mensaje de agradecimiento a un cliente habitual, el aviso de una promoción y la invitación a un evento especial. Al expresar tu sinceridad en un texto elegante, profundizas todavía más la relación con el cliente.', 'Escribe un mensaje breve y cálido, personalizado, para 3 clientes habituales a los que voy a contactar hoy. Que se note la sinceridad y que invite, con naturalidad, a volver a la tienda.'),
        T('Mealime', 'specialist', 'Mantén una alimentación equilibrada incluso en un terreno de ventas ajetreado', 'Mantén una alimentación equilibrada incluso en un terreno de ventas ajetreado. Con un plan de comidas de IA, sostienes la energía de forma estable y puedes mantener, todo el día, una energía cálida de ventas.', 'Arma un almuerzo simple y equilibrado, que se pueda preparar o pedir en poco tiempo, para sostener la energía de la tarde en un día de ventas en la tienda.'),
        T('Wysa', 'specialist', 'Gestiona la fatiga emocional que deja una queja de precio o una situación difícil', 'Gestiona la fatiga emocional que llega de una queja de precio de un cliente o de una situación difícil. Aunque tengas un carácter optimista, una experiencia negativa repetida con un cliente se acumula. Con una revisión emocional periódica, previenes el agotamiento.', 'Hoy recibí varias quejas de precio y me quedó una fatiga emocional. Guía una revisión breve de 3 minutos para soltar esa tensión y prevenir el agotamiento, sin perder la calidez con el siguiente cliente.')],
    syn: 'El socio con el que más sinergia tienes es un colega minucioso, fuerte en una gestión sistemática del inventario y en la operación de la tienda. La división de roles es natural: tú llevas la relación con el cliente y ellos gestionan la eficiencia de la operación. A un cliente habitual, envíale con regularidad, con ChatGPT, un mensaje de agradecimiento y un beneficio especial, mantén la relación y crea una cultura de referidos en la que te presenten a alguien conocido.',
    day: 'A las 8:30 de la mañana, escribes con ChatGPT el mensaje personalizado que vas a enviar a 3 clientes habituales a los que contactarás hoy. Incluyes una frase cálida que encaje con el rasgo de cada uno. A las 9:00, al abrir la tienda, recibes al cliente con ánimo. A media mañana sigues una comunicación natural con quien entra y te concentras en crear un habitual nuevo. En el almuerzo, con Mealime, cuidas la comida para la energía de la tarde. En un momento breve, revisas con Wysa tu estado emocional de la mañana. Por la tarde profundizas el vínculo que creaste en la mañana y te concentras en la comunicación con los habituales. Antes del cierre, escribes con ChatGPT el mensaje de agradecimiento que vas a enviar al cliente nuevo que conociste hoy, y lo envías.'
  });
  add('00111', 'El solucionador despreocupado de la tienda, el conector del equipo de retail', 'ChatGPT', ['Canva Magic', 'Zapier'], {
    i: 'Eres el generador de energía de la tienda. La combinación de una apertura y una responsabilidad bajas, una extraversión y una amabilidad altas, y un neuroticismo alto produce al especialista animado en ventas que, en el terreno del retail, lidera el ambiente y se acerca al cliente de forma natural. Más que una estrategia compleja, eres excepcional limpiando un inventario difícil y dando vuelta el ambiente, con una capacidad de comunicación del momento y un sentido de terreno. La sinergia de una extraversión y una amabilidad altas hace que incluso un cliente que acabas de ver se sienta cómodo enseguida, y que la decisión de compra siga como un flujo natural. Cuando el ambiente de la tienda se cae, si tú solo enciendes una chispa, se anima la energía de todo el equipo. Un neuroticismo alto te hace reaccionar con más fuerza a no alcanzar un objetivo o a la queja de un cliente. Pero esa sensibilidad, al contrario, se convierte en el motivo de mantener un listón alto de servicio al cliente. Tu forma de concretar con rapidez, con ChatGPT, una idea improvisada de una promoción, de producir de inmediato, con Canva Magic, el material de un evento de terreno, y de automatizar el trabajo repetido con Zapier, combina la velocidad y la creatividad de una venta de terreno.',
    s: [
      'La capacidad de gestionar la energía del terreno, que convierte de inmediato el ambiente de la tienda en algo animado y estimula, de forma natural, el deseo de compra del cliente.',
      'Una afinidad que, en solo unos minutos, forma una relación cercana con un cliente que acabas de conocer, baja la reserva y sigue, de forma natural, hacia una conversación de compra.',
      'Una capacidad improvisada de resolver un problema, que agota con rapidez, con una idea creativa de terreno, un inventario acumulado o un producto de una campaña.'
    ],
    g: [
      'Como un neuroticismo alto puede hacerte estresar en exceso cuando no se alcanza un objetivo, toma el hábito de fijar un subobjetivo de cada día y de reconocer, de forma consciente, cada logro.',
      'Como una responsabilidad baja puede hacer que se atrase una tarea administrativa, como la gestión del inventario o el cierre, fija de forma obligatoria los 10 minutos del final de la jornada como horario de trámite administrativo.'
    ],
    t: [T('ChatGPT', 'main', 'Escribe en un instante el texto de una promoción improvisada, el discurso de un evento y un aviso que atraiga la mirada', 'Escribe en un instante el texto de una promoción improvisada, el discurso de un evento y la copia de un aviso de la tienda que atraiga la mirada del cliente. Si solo lanzas la idea, obtienes de inmediato una frase potente, lista para usar en el terreno.', 'Dame 3 ideas de una promoción de hoy y el discurso corto para el piso de la tienda, para agotar un inventario acumulado y animar el ambiente. Que se pueda usar de inmediato.'),
        T('Canva Magic', 'specialist', 'Produce con rapidez el póster de un evento de terreno, un cartel de precios y una imagen de promoción para redes', 'Produce con rapidez el póster de un evento de terreno, un cartel de precios y una imagen de una promoción para redes. Con la función de diseño de la IA, incluso sin una preparación previa, armas de inmediato un material visual profesional y levantas el ambiente de la tienda.', 'Arma un póster de un evento de esta tarde en la tienda y una imagen de promoción para redes, con un diseño profesional, a partir de este texto de la promoción.'),
        T('Zapier', 'specialist', 'Automatiza la recolección de un contacto, el mensaje de una promoción y el aviso de inventario', 'Automatiza el trabajo repetido, como recolectar el contacto de un cliente, enviar un mensaje de aviso de una promoción o un aviso de inventario. Al reducir la carga administrativa, te aseguras el tiempo de concentrarte en lo que mejor se te da: la comunicación con el cliente en el terreno.', 'Automatiza la recolección de contactos de los clientes de hoy, el envío programado del mensaje de aviso de la promoción del día y un aviso cuando baje el inventario de un producto de la campaña.')],
    syn: 'El socio con el que más sinergia tienes es un colega minucioso, fuerte en una gestión sistemática del inventario y en el análisis de datos. La división de roles en la que, mientras tú despliegas una energía explosiva en la venta de terreno, ellos gestionan los datos y el inventario, sube la eficiencia de toda la tienda. Dentro del equipo, ofrécete como el banco de ideas y, en la reunión semanal, comparte una idea de ventas de terreno. Tu sentido de terreno enriquece la estrategia de ventas de todo el equipo.',
    day: 'A las 8:30 de la mañana, antes de abrir la tienda, preparas con ChatGPT 2 o 3 discursos de un evento de hoy y una idea de una promoción. Inviertes tiempo en fijar el ambiente de la tienda. A las 9:00, al abrir, recibes con ánimo al primer cliente. Por la mañana maximizas el punto de contacto con el cliente y llevas un evento de terreno. Si hay inventario acumulado, desarrollas un discurso especial y lo agotas con iniciativa. En el almuerzo, armas con rapidez, con Canva Magic, el póster del evento de la tarde y programas con Zapier el envío del mensaje de aviso de la promoción del día. Por la tarde recibes al cliente con una energía todavía más alta que la de la mañana. Desde 30 minutos antes del cierre, llevas una campaña de cierre para alcanzar el objetivo de ventas de hoy. 10 minutos antes del cierre, terminas el trámite administrativo y la preparación del día siguiente.'
  });
  add('01000', 'El manual es la ley: el devoto estricto de las directrices', 'Perplexity', ['Grammarly', 'Snyk'], {
    i: 'Eres el guardián del principismo de la tienda. La combinación de una apertura baja y una responsabilidad alta, una extraversión y una amabilidad bajas, y un neuroticismo bajo produce al especialista minucioso y principista en ventas, que aplica con exactitud incluso el artículo 4, apartado 2, de la norma de descuentos, y no admite ni un 0,1% de excepción. Compites más con un conocimiento verificado del producto y con la norma interna que con una oratoria brillante, y cumples con precisión tu rutina y tu criterio. La combinación de una responsabilidad alta y un neuroticismo bajo te permite mantener, por ti mismo, un listón alto, sin una presión externa, y realizar un trabajo exacto, sin estrés. En tu cierre no hay ni un error de 1 won, y la cantidad de inventario coincide siempre por completo con el sistema. Esta exactitud se convierte en la base que sostiene una operación transparente de la empresa. La combinación de una amabilidad y una extraversión bajas puede hacerte sentir incómoda la comunicación cotidiana con un cliente. Pero, muchas veces, una atención clara, basada en la norma, le da más bien una sensación de confianza. La rutina de captar con Perplexity la norma más reciente de una disputa de consumo, de terminar con Grammarly una comunicación oficial y de gestionar con Snyk la seguridad del sistema digital de la tienda, maximiza tu fortaleza.',
    s: [
      'Una especialidad que, al dominar a la perfección la norma de operación de la tienda y el criterio de protección al consumidor, responde con claridad, con un fundamento legal, en cualquier disputa.',
      'Una confiabilidad que mantiene una exactitud perfecta en el inventario, el cierre y cada documento, y que no presenta ningún problema ni en una auditoría ni en una inspección.',
      'Una independencia psicológica que, sin tambalearte ante una presión externa o una petición de un cliente, mantienes tu criterio de forma consistente.'
    ],
    g: [
      'Como una amabilidad y una extraversión bajas pueden volver demasiado oficial la comunicación con un cliente, practica, antes de explicar la norma, reconocer en aunque sea una frase la situación del cliente.',
      'Como la tendencia a rechazar un cambio puede atrasar la introducción de un canal digital de ventas o de un sistema nuevo de pago, arma un plan de introducción gradual y acepta el cambio con seguridad.'
    ],
    t: [T('Perplexity', 'main', 'Captas de inmediato, con hechos, el criterio de una disputa de consumo y la norma más reciente', 'Captura de inmediato, centrado en los hechos, el criterio complejo de resolución de una disputa de consumo, la normativa más reciente de un contrato y la norma de un reembolso o un cambio. En una disputa con un cliente, confirmas al instante el fundamento legal y garantizas una atención exacta y justa.', 'Resúmeme, con fuentes, el criterio legal y la norma interna aplicables a esta disputa de un reembolso y un cambio. Necesito una base exacta para responderle al cliente de forma justa.'),
        T('Grammarly', 'specialist', 'Escribe con exactitud y profesionalidad una carta oficial, una respuesta a una queja y un informe a la casa matriz', 'Escribe con exactitud y profesionalidad una carta oficial a un cliente, un documento de respuesta a una queja y un informe a la casa matriz. Tu posición principista queda expresada en un lenguaje claro y evitas un malentendido innecesario.', 'Revisa esta carta oficial de respuesta a una queja de un cliente: que el tono sea profesional, que la norma quede clara y que no se preste a un malentendido.'),
        T('Snyk', 'specialist', 'Revisa con regularidad una vulnerabilidad de seguridad del POS, del inventario y de la base de datos de clientes', 'Revisa con regularidad una vulnerabilidad de seguridad del sistema POS de la tienda, del software de gestión de inventario y de la base de datos de clientes. Al proteger con seguridad los datos personales del cliente y los datos de una transacción de la tienda, previenes un riesgo legal.', 'Arma una lista de verificación semanal para revisar una vulnerabilidad de seguridad del POS, del software de inventario y de la base de datos de clientes de la tienda, y dime qué debo comprobar primero hoy.')],
    syn: 'El socio con el que más sinergia tienes es un compañero extravertido del equipo, que lleva la relación con el cliente y el ambiente de la tienda. La división de roles se da de forma natural: tú mantienes el criterio de operación y la exactitud, y ellos se encargan de una comunicación cálida con el cliente. Recuerda que tu dato perfecto de cierre y tu registro de cumplimiento de la norma se convierten en un activo que sube la confiabilidad de todo el equipo, y toma eso como fundamento de orgullo.',
    day: 'A las 8:00 en punto de la mañana, empiezas el día en el orden de la lista de verificación. Vuelves a confirmar el cierre de ventas de ayer y contrastas el inventario del sistema con el físico. A las 8:30, si hay una disputa de consumo o una queja que hay que tramitar hoy, primero confirmas con Perplexity la norma aplicable. A las 9:00, después de abrir la tienda, atiendes con exactitud, conforme a la norma, a los primeros clientes. A media mañana revisas el ingreso de inventario de hoy y el estado de la exhibición. Una vez a la semana, revisas con Snyk el estado de seguridad del sistema de la tienda. Después del almuerzo, cierras el historial de transacciones de la mañana y envías la carta oficial que escribiste con Grammarly. Por la tarde te concentras en tramitar una disputa con un cliente y en terminar el cierre. Antes de irte, terminas un cierre diario perfecto y la preparación del día siguiente.'
  });
  add('01001', 'El CRM humano: el estratega de ventas que compite con datos', 'Perplexity', ['Gong.io', 'Tableau'], {
    i: 'Eres el científico frío del mundo de las ventas. La combinación de una apertura baja y una responsabilidad alta, una extraversión y una amabilidad bajas, y un neuroticismo alto produce al estratega que diseña una venta con datos, no con emoción. Analizas, hasta el decimal, el ciclo de compra de un cliente, el ticket promedio y el patrón de salida, y te acercas con exactitud al objetivo de mayor probabilidad. Una extraversión y una amabilidad bajas te llevan a concentrarte, más que en una red amplia, en una relación profunda con un número reducido de clientes clave. Eso parece un punto débil, pero, en realidad, es la razón por la que tu tasa de conversión de ventas supera con mucho el promedio del sector. Tu forma de golpear con exactitud, más que de desplegar en amplio, produce, a largo plazo, un ROI más alto. Un neuroticismo alto te hace reaccionar con sensibilidad a la variación de un resultado. Si aparece la señal de que podrías no alcanzar el objetivo del trimestre, tiendes a inquietarte. La rutina de reunir datos del mercado con Perplexity, de analizar una conversación de ventas con Gong.io y de visualizar los datos de ventas con Tableau convierte esa inquietud en una acción concreta. Confía en el hecho que muestran los datos y muévete en la dirección que señalan.',
    s: [
      'Una capacidad de venta basada en datos que, al analizar con precisión los datos de un cliente y el patrón de compra, identifica con exactitud el objetivo con la mayor posibilidad de un cierre.',
      'Una capacidad de aproximación lógica que ejecuta, de forma consistente, una estrategia de ventas basada en un fundamento estadístico, sin emoción ni un juicio improvisado.',
      'Una capacidad de análisis del mercado que monitorea de forma continua la promoción de un competidor y el cambio del mercado, y arma una estrategia de ventas anticipada.'
    ],
    g: [
      'Como la inquietud por un resultado, que viene de un neuroticismo alto, puede convertirse en una obsesión con la venta de corto plazo, rastrea también el indicador de valor de largo plazo del cliente (LTV) y mantén una perspectiva de ventas equilibrada.',
      'Como una amabilidad baja puede volver demasiado transaccional la relación con un cliente, una vez cada trimestre, mantén el vínculo humano con un contacto de cortesía, sin relación con un resultado, para saber cómo está.'
    ],
    t: [T('Perplexity', 'main', 'Captas de inmediato, con una fuente exacta, la promoción de un competidor y el cambio de la cuota de mercado', 'Captura de inmediato, junto con una fuente exacta, el estado de una promoción de un competidor, el cambio de la cuota de mercado y la tendencia del sector. Antes de una reunión con un cliente, investigas con rapidez el tema más reciente de esa industria y refuerzas el fundamento lógico de la venta.', 'Resúmeme, con fuentes, en 5 minutos, la noticia más reciente del sector de la empresa del cliente con la que me reúno hoy, el estado de una promoción de un competidor y un cambio de la cuota de mercado.'),
        T('Gong.io', 'specialist', 'Analiza en automático una llamada y una reunión de ventas, y encuentra el patrón de un cierre', 'Analiza en automático una llamada y una reunión de ventas, y captura el patrón de éxito y el punto de mejora. Al aprender con datos qué patrón de conversación lleva a un cierre, optimizas de forma continua el guion de ventas.', 'Analiza las llamadas y las reuniones de ventas de esta semana y dime qué patrón de conversación llevó a un cierre, y qué punto debo mejorar en el guion.'),
        T('Tableau', 'specialist', 'Visualiza en un tablero el pipeline, la tasa de conversión y el resultado por segmento de cliente', 'Visualiza en un tablero el pipeline de ventas, la tasa de conversión y el resultado por segmento de cliente. Al captar el estado de las ventas con base en datos, reduces la inquietud ante la variación de un resultado y resulta posible una corrección exacta de la estrategia.', 'Arma un tablero del pipeline de esta semana, de la tasa de conversión y del resultado por segmento, y señala los 3 objetivos de cierre de mayor probabilidad para hoy.')],
    syn: 'El socio con el que más sinergia tienes es un responsable de ventas extravertido, fuerte en la relación interpersonal y en el cierre. La división de roles en la que tú descubres el objetivo con datos y diseñas la estrategia, y ellos la ejecutan con energía frente al cliente, maximiza la eficiencia de ventas de todo el equipo. Cada lunes, revisa con el tablero de Tableau el estado de las ventas del equipo y comparte con claridad el objetivo de concentración y la estrategia de esta semana.',
    day: 'A las 7:30 de la mañana, revisas con el tablero de Tableau el resultado de ventas de ayer. Captas el estado del pipeline y los cierres previstos, y fijas la prioridad de hoy. A las 8:30, captas en 5 minutos, con Perplexity, la noticia más reciente del sector de la empresa del cliente con la que vas a contactar hoy. Terminas de forma sistemática la preparación de antes de la reunión. Desde las 9:00 empiezan las reuniones. Después de cada una, registras de inmediato el resultado del análisis de Gong.io y el hallazgo central. Después del almuerzo, actualizas con Tableau el resultado de ventas de la mañana y reajustas la prioridad de la tarde. Con Perplexity, investigas información adicional sobre una empresa concreta de un cliente. Por la tarde te concentras en un cliente clave, con una alta posibilidad de un cierre. Antes de irte, analizas en conjunto los datos de ventas de esta semana y actualizas la lista de objetivos de la semana que viene.'
  });
  add('01010', 'El asesor de corazón blando, el hada invisible del cliente', 'Claude', ['Grammarly', 'Wysa'], {
    i: 'Eres el guardián callado de la atención al cliente. La combinación de una apertura baja y una responsabilidad alta, una extraversión baja, una amabilidad alta y un neuroticismo bajo produce al empático principista que atiende a la perfección, conforme al manual y, a la vez, empatiza de verdad con una situación difícil del cliente. Tu filosofía de trabajo es, dentro del marco de la norma, buscar la vía que más ayude al cliente. La combinación de una responsabilidad y una amabilidad altas produce al asesor equilibrado que trata con esmero a cada cliente y, aun así, jamás baja el criterio del trabajo. El cliente que recibió tu atención se queda satisfecho, con la sensación de haber recibido la mejor ayuda posible, también dentro de la norma. Gracias a un neuroticismo bajo, tienes una estabilidad interior que no se tambalea ni ante un consumidor abusivo ni ante una queja forzada. Eso previene el agotamiento del trabajo de atención y hace posible un servicio continuo de alta calidad. Tu rutina de preparar con Claude una respuesta empática a una queja sensible, de subir con Grammarly la calidad de una comunicación oficial y de cuidar con Wysa tu propia salud emocional, te hace crecer, a largo plazo, como un especialista excepcional en atención.',
    s: [
      'Una capacidad equilibrada de atención que, al cumplir la norma y el principio y, a la vez, empatizar de verdad con la situación del cliente, deja satisfechas a ambas partes.',
      'Una estabilidad psicológica que, incluso en una situación difícil con un cliente, no se tambalea a nivel emocional y mantiene una calidad de servicio consistente.',
      'Una capacidad de cierre que registra con minucia el trabajo de atención y cumple por completo el seguimiento, de modo que el cliente siente que lo cuidaron hasta el final.'
    ],
    g: [
      'Como una responsabilidad alta puede llevarte a intentar un apoyo al cliente que supera el alcance de tu rol y provocar un agotamiento, define con claridad lo que sí puedes hacer y ese alcance.',
      'Como una apertura baja puede hacerte sentir resistencia ante la introducción de un proceso o un sistema nuevo de atención, desarrolla la flexibilidad de aceptar, de forma gradual, un método nuevo, con un período de prueba.'
    ],
    t: [T('Claude', 'main', 'Escribe con empatía y claridad la respuesta a una queja compleja, un correo que explica la norma y una disculpa', 'Escribe con empatía y claridad el texto de respuesta a una queja compleja, un correo que explica la norma y una carta de disculpa por una queja del cliente. Pule la expresión para que tu sinceridad se transmita, sin un malentendido, también en el formato de un escrito oficial.', 'Escribe una respuesta oficial, empática y clara, a esta queja sensible de un cliente. Reconoce su situación, explica la norma sin un malentendido y propone la mejor ayuda posible dentro de ese marco.'),
        T('Grammarly', 'specialist', 'Revisa la gramática y la expresión de un correo oficial, un expediente de una queja y un informe interno', 'Revisa la gramática y la expresión de un correo oficial a un cliente, de un expediente de trámite de una queja y de un informe interno. Con una calidad profesional del lenguaje, garantizas una comunicación que le da confianza tanto al cliente como a un superior.', 'Revisa este correo oficial de trámite de una queja: que la gramática y el tono sean profesionales, y que le dé confianza tanto al cliente como a un superior.'),
        T('Wysa', 'specialist', 'Revisa y recupera la fatiga psicológica de después de una atención emocionalmente difícil', 'Después de una atención a una queja emocionalmente difícil, revisa y recupera la fatiga psicológica. Te ayuda a reconocer tu propio estado emocional y a mantener un límite sano.', 'Acabo de terminar una atención difícil a una queja. Guía una revisión breve para soltar la fatiga emocional, reconocer cómo estoy y mantener un límite sano antes de la siguiente conversación.')],
    syn: 'El socio con el que más sinergia tienes es un colega de perfil innovador, que impulsa un sistema nuevo de atención y la mejora de un proceso. La división de roles es natural: ellos sistematizan el saber de atención que tú acumulaste en el terreno, y tú ejecutas con la mayor fidelidad el sistema mejorado. Comparte con todo el equipo la experiencia de haber resuelto una queja difícil, y conviértela en un conocimiento colectivo.',
    day: 'A las 8:00, revisas la lista de atenciones reservadas de hoy y captas de antemano un caso complejo. Para una atención difícil, preparas con Claude la dirección de la respuesta. Desde las 9:00 empiezan las atenciones. Después de cada una, escribes con Grammarly el correo oficial necesario y lo envías. En el almuerzo, revisas con Wysa la fatiga emocional acumulada en las atenciones de la mañana. Preparas el ánimo para las de la tarde. Por la tarde tramitas, con un alto grado de acabado y con la ayuda de Claude, una queja compleja o un caso difícil. A última hora de la tarde, resuelves todos los pendientes de las atenciones de hoy y terminas la preparación del día siguiente. Antes de irte, cierras con Wysa el estado emocional del día y, después del trabajo, te separas por completo de la tarea.'
  });
  add('01011', 'El hada invisible y callada, el maestro oculto de la atención al cliente', 'ChatGPT', ['Monday.com', 'Notion AI'], {
    i: 'Eres quien, sin que se te vea, termina la atención al cliente. La combinación de una apertura baja y una responsabilidad alta, una extraversión baja, una amabilidad alta y un neuroticismo alto produce al asesor maestro oculto, que no se pone al frente y, en silencio, resuelve a la perfección lo que el equipo dejó pendiente. Eres el hada invisible del equipo, que tramita en silencio, y a la perfección, un reclamo complejo, y que también cuida un caso sin resolver de un colega. La combinación de una responsabilidad y una amabilidad altas te da la capacidad de cerrar hasta el final cada caso de un cliente y, en ese proceso, de hacer que sienta que lo cuidaron lo bastante. Después de una atención contigo, el cliente siente calidez, junto con la certeza de que quedó resuelto. Un neuroticismo alto puede provocar una preocupación excesiva en una queja compleja o en una situación difícil con un cliente. Tu forma de automatizar con ChatGPT una queja repetida, de sistematizar con Monday.com la gestión de un caso y de ir acumulando, con Notion AI, el saber de la atención al cliente, sube al mismo tiempo la eficiencia y la calidad del trabajo de atención.',
    s: [
      'Una responsabilidad que cierra hasta el final cualquier queja compleja de un cliente, y una afinidad cálida que, en ese proceso, hace que el cliente sienta que lo cuidaron lo bastante.',
      'Una capacidad de apoyo colaborativo que, de forma voluntaria, cuida un caso sin resolver de todo el equipo y sube la satisfacción del cliente de todo el equipo.',
      'Una capacidad de uso de herramientas que aprende con rapidez una herramienta nueva de CRM y un sistema de atención, y sube la eficiencia del trabajo de todo el equipo.'
    ],
    g: [
      'Como un neuroticismo alto puede hacerte volcar una energía excesiva en un caso difícil y provocar un agotamiento, define con claridad el alcance de lo que sí se puede resolver y, más allá de eso, arma el criterio de escalarlo a un superior.',
      'Como una extraversión baja a veces hace que, dentro de la organización, no te reconozcan tu resultado y tu aporte, toma el hábito de registrar y visibilizar, cada mes, los casos tramitados y la satisfacción del cliente.'
    ],
    t: [T('ChatGPT', 'main', 'Arma un sistema de respuesta automática y un guion de atención para una consulta repetida', 'Arma un sistema de respuesta automática y un guion de atención para una consulta repetida de un cliente. Creas tu propio GPT de atención al cliente, para que una atención de una calidad consistente se produzca en automático.', 'Arma un guion de respuesta automática, de una calidad consistente, para las 10 consultas de clientes que más se repiten este mes, y dime cómo convertirlo en un GPT de atención.'),
        T('Monday.com', 'specialist', 'Gestiona de forma visual, por caso, el avance, el responsable y la fecha límite', 'Gestiona de forma visual, por caso de un cliente, el avance, el responsable y la fecha límite de trámite. Todo el equipo comparte el estado de un caso y se rastrea para que no se omita uno sin resolver.', 'Arma un tablero de Monday.com con los casos de hoy y los pendientes de ayer, con responsable, fecha límite y prioridad, para que no se omita ningún caso sin resolver.'),
        T('Notion AI', 'specialist', 'Documenta de forma sistemática un caso de una queja compleja y el saber de la atención', 'Documenta de forma sistemática un caso de resolución de una queja compleja y el saber de la atención al cliente. Con una búsqueda de IA, encuentras de inmediato el método de resolución de un caso similar, lo tomas como referencia y armas una base de conocimiento que sube de forma continua la capacidad de atención de todo el equipo.', 'Documenta el método de resolución de la queja compleja de hoy y búscame, en la base de conocimiento, un caso similar que pueda usar como referencia para la siguiente atención.')],
    syn: 'El socio con el que más sinergia tienes es un colega de perfil innovador, que diseña y mejora el proceso de atención al cliente. La colaboración en la que ellos convierten en un sistema el saber y el caso que tú acumulaste en una atención real sube la capacidad de atención de todo el equipo. Comparte con todo el equipo el conocimiento de atención que has ido acumulando en Notion AI y, con regularidad, presenta el método de resolución de un caso difícil, para visibilizar tu especialidad oculta.',
    day: 'A las 8:00, revisas con Monday.com los casos que hay que tramitar hoy y los pendientes de ayer. Fijas la prioridad y captas primero un caso complejo. A las 8:30, revisas en el sistema de respuesta automática de ChatGPT las consultas de clientes que entraron hoy y compruebas si se tramitaron en automático. Clasificas las que piden un trámite manual. Desde las 9:00 empiezan las atenciones. En una queja compleja, consultas en Notion AI el método de resolución de un caso similar. Después del almuerzo, actualizas en Monday.com el estado de cierre de los casos de la mañana y reajustas la prioridad de la tarde. Por la tarde te concentras, en especial, en un caso difícil. El método de un caso que resolviste lo registras de inmediato en Notion AI. Antes de irte, confirmas en Monday.com el cierre de todos los casos de hoy y dejas una nota clara en los que pasan a mañana.'
  });
  add('01100', 'Quien habla con números: el vendedor de resultados', 'HubSpot AI', ['ChatGPT', 'Notion AI'], {
    i: 'Tú, que adelantaste 3 días el cumplimiento del objetivo del mes, ya estás analizando el del mes que viene. Con una capacidad sistemática de ejecución, de un 79% de responsabilidad, y un impulso de un 74% de extraversión, eres, en el área de ventas, “el vendedor de resultados que habla con números”. Con una amabilidad baja (21%) te concentras más en la prueba de valor y en el contrato que en una conexión emocional con el cliente, y con una apertura también baja (26%) confías en una forma de vender ya verificada. Con un neuroticismo bajo (19%) no te tambaleas ni ante un rechazo ni ante la presión de un objetivo. Esta combinación es el perfil de “top performer” que produce, en el equipo, el mayor número de contratos y de ventas.',
    s: [
      'Una capacidad de ejecución que supera el objetivo: con una responsabilidad y una extraversión altas, mantienes el volumen más alto de actividad de ventas (llamadas, reuniones, propuestas), y eso se conecta de forma natural con el mejor resultado. Hay la confianza de que ningún mes queda por debajo del objetivo.',
      'Una venta centrada en la prueba de valor: con una amabilidad baja, no dependes de la cercanía y demuestras el valor real de nuestro producto o servicio con datos y con un caso. Una venta que persuade con lógica, no con emoción, es la más convincente en B2B.',
      'Una negociación fría bajo presión: con un neuroticismo bajo, aunque el cliente presione el precio, no te desconciertas, sostienes nuestro valor y negocias. Tienes la capacidad de llevar un contrato también sin un descuento excesivo.'
    ],
    g: [
      'Invertir en la relación con el cliente: con una amabilidad baja, el mantenimiento de la relación de después de un contrato se puede descuidar y bajar la tasa de renovación. Si, una vez al trimestre, inviertes en una conversación fuera del negocio (cómo está, compartir información del sector), sube la tasa de renovación.',
      'Aceptar una innovación en el método de ventas: con una apertura baja, puedes resistirte a una técnica nueva (venta en redes, venta con contenido). Arma la rutina de, una vez al trimestre, hacer un piloto de un método nuevo ya verificado.'
    ],
    t: [T('HubSpot AI', 'main', 'La optimización del pipeline de ventas y el seguimiento del resultado', 'HubSpot AI optimiza, con datos, la actividad de ventas de alguien como tú, de una responsabilidad alta. Si la IA analiza la tasa de conversión por etapa del pipeline, el ciclo promedio de un contrato y el patrón de éxito, queda claro en qué hay que concentrarse para ser más eficiente.', 'HubSpot AI, clasifica, en el pipeline de este mes, los casos en los que es posible cerrar un contrato dentro de esta semana. En cada uno, dime la probabilidad del contrato, el importe previsto y la acción decisiva de cierre.'),
        T('ChatGPT', 'specialist', 'Refuerza la estrategia de negociación y la propuesta de valor', 'ChatGPT es el socio que vuelve todavía más potente tu venta de prueba de valor. Cuando el cliente pone en cuestión el precio, puedes armar de inmediato, con ChatGPT, un material que calcule “el ROI de nuestra solución y el ahorro real del cliente”.', 'ChatGPT, mañana tengo la negociación de un contrato anual con un fabricante de 20.000 millones de wones de ventas al año. Parece que el cliente va a pedir una bajada del 5% del precio. Convierte en un importe el valor que nuestro producto le dio a este cliente en el último año (una subida del 15% de la productividad, una bajada del 30% de la tasa de defectos) y arma la posición de negociación.'),
        T('Notion AI', 'specialist', 'El análisis del resultado de ventas y la optimización de la estrategia', 'Notion AI acumula los datos de tu resultado de ventas y analiza el patrón. Si rastreas la tasa de cumplimiento mensual, la tasa de conversión a contrato por tipo de cliente y el ciclo promedio de un contrato, sale con datos una estrategia de ventas más eficiente.', 'Notion AI, analiza mi resultado de ventas de este trimestre. Ordena el número de contratos, las ventas totales, la tasa de cumplimiento del objetivo y el resultado por tipo de cliente y por sector, y propone 3 direcciones de venta en las que concentrarme el trimestre que viene.')],
    syn: 'Tú, que con una responsabilidad y una extraversión altas produces el mejor resultado con el mayor volumen de actividad, eres el top performer del equipo de ventas. Si optimizas el pipeline con HubSpot AI, preparas la negociación con ChatGPT y analizas el resultado con Notion AI, creces de un resultado individual a un líder que sube la capacidad de ventas de todo el equipo.',
    day: '08:30 Revisas con HubSpot AI la lista de leads prioritarios y de follow-up de hoy. 09:00 Preparas con ChatGPT la negociación o la reunión de hoy. 10:00 Concentración en reuniones con clientes (horario de outreach de la mañana). 13:30 Actualizas en HubSpot el registro de la actividad de la mañana. 14:00 Redacción de una propuesta y envío de correos. 16:00 Revisas con Notion AI el estado de las ventas de esta semana. 17:00 Preparación de la reunión de mañana y revisión, con ChatGPT, de la estrategia de negociación.'
  });
  add('01101', 'El gerente estricto de la tienda, el tigre supervisor de la oficina', 'Perplexity', ['BlackLine', 'Clockify'], {
    i: 'Eres el hombre o la mujer de hierro de la tienda. La combinación de una apertura baja y una responsabilidad alta, una extraversión alta, una amabilidad baja y un neuroticismo alto produce al gerente potente que sacraliza el manual y el principio, y mantiene a fondo la disciplina de la tienda. No admites ni un error de 1 grado en el ángulo de una exhibición, y no doblas el principio ante ninguna petición forzada de un cliente. La combinación de una responsabilidad y una extraversión altas produce al líder con capacidad de ejecución que, como gerente, inspecciona el terreno en persona y les transmite al equipo un criterio claro. Eres un gerente al que se teme y, a la vez, se le tiene confianza. Como tratas con justicia, conforme al principio, los empleados confían en tu juicio. Un neuroticismo alto puede hacerte estresar en exceso cuando la tienda no llega al criterio. Tu forma de captar con Perplexity la ley más reciente de protección al consumidor y la norma de gestión de la tienda, de gestionar con precisión las finanzas de la tienda con BlackLine y de rastrear con Clockify la eficiencia del trabajo del equipo, refuerza con datos una gestión basada en el principio.',
    s: [
      'Una capacidad de gestión consistente que mantiene a fondo el criterio de operación de la tienda y, en cualquier situación, no dobla el principio.',
      'Una capacidad de cumplimiento normativo que, al dominar a la perfección desde la ley de protección al consumidor hasta la norma interna, resuelve cualquier disputa con base en los hechos.',
      'Una capacidad justa de gestión que rastrea con datos la eficiencia y el resultado del trabajo del equipo, y evalúa y apoya a un compañero con un criterio objetivo.'
    ],
    g: [
      'Como un neuroticismo alto te lleva a reaccionar en exceso cuando no se llega al criterio, desarrolla la flexibilidad de clasificar un tema por importancia y de tramitar uno no central con coaching.',
      'Como una amabilidad baja puede dejar corta la relación humana con el equipo, una vez al mes, crea un horario informal de comunicación del equipo, sin relación con un resultado, y refuerza la relación de confianza.'
    ],
    t: [T('Perplexity', 'main', 'Captas con exactitud la ley de protección al consumidor, la norma de la tienda y un cambio laboral', 'Captura con exactitud la ley más reciente de protección al consumidor, la norma de gestión de la tienda y un cambio de la legislación laboral. En una disputa con un cliente o en un tema de gestión de un empleado, confirmas de inmediato el fundamento legal y resuelves el problema con hechos, sin emoción.', 'Resúmeme, con fuentes, el cambio más reciente de la ley de protección al consumidor y de la legislación laboral que aplique a una disputa de hoy en la tienda o a un tema de gestión de un empleado. Necesito un fundamento legal exacto, sin emoción.'),
        T('BlackLine', 'specialist', 'Cierra en automático las ventas, los costos y las finanzas de inventario, y detecta un valor anómalo', 'Cierra en automático los datos financieros de las ventas diarias, los costos y el inventario de la tienda, y detecta un valor anómalo. Subes la transparencia financiera y descubres a tiempo un error pequeño, antes de que se convierta en un problema grande.', 'Revisa el cierre financiero de ayer de la tienda —ventas, costos e inventario— y señala cualquier valor anómalo o error pequeño que deba corregirse antes de que se vuelva un problema.'),
        T('Clockify', 'specialist', 'Rastrea el tiempo de trabajo y la productividad de cada persona, y arma un dato objetivo de resultado', 'Rastrea el tiempo de trabajo y la productividad de cada persona del equipo, y aseguras un dato objetivo de resultado. Armas un criterio justo de evaluación, identificas un tramo de ineficiencia del trabajo y optimizas la operación de la tienda.', 'Resume el tiempo de trabajo y la productividad del equipo de esta semana, señala el tramo de ineficiencia y propón un criterio objetivo que pueda usar en la evaluación.')],
    syn: 'El socio con el que más sinergia tienes es un compañero afable del equipo, fuerte en la relación con el cliente y en formar el ambiente del equipo. La división de roles en la que tú fijas el criterio y el principio, y ellos llevan al equipo y al cliente de una forma cálida, sube al mismo tiempo la eficiencia y el ambiente de toda la tienda. Cada semana, revisa el resultado del equipo con los datos de Clockify, pero asigna también un tiempo para captar la situación de cada persona que hay detrás del número.',
    day: 'A las 8:00, antes de abrir la tienda, revisas con Perplexity si hay un tema de norma que hay que tramitar hoy. Revisa con BlackLine el estado financiero de la tienda de ayer. A las 8:30 inspeccionas en persona el estado de la exhibición y lo ajustas al criterio. A las 9:00, en el briefing del equipo, transmites con claridad el punto central y el criterio de hoy. A media mañana monitoreas el trabajo del equipo y, si hace falta, das coaching de inmediato. Confirmas que el seguimiento del tiempo de trabajo con Clockify se esté haciendo bien. Después del almuerzo, tramitas una disputa con un cliente o un tema de norma. Confirmas de inmediato la norma aplicable con Perplexity. Por la tarde preparas el plan de operación de la tienda del mes que viene y la evaluación del resultado del equipo. Antes de irte, cierras con BlackLine las finanzas de la tienda de hoy.'
  });
  add('01110', 'El maestro de la venta relacional, que hace crecer el negocio a través de las personas', 'HubSpot AI', ['Claude', 'Notion AI'], {
    i: 'Aunque el responsable de una empresa cliente se cambie de compañía, te contacta primero a ti: “también allí quiero trabajar contigo.” Con una gestión sistemática de un 80% de responsabilidad, una capacidad profunda de relación de un 83% de amabilidad y una capacidad de comunicación de un 73% de extraversión, eres, en el área de ventas y de gestión de clientes, “el maestro de la venta relacional que hace crecer el negocio a través de las personas”. Con una apertura baja (27%) prefieres una forma ya verificada, y con un neuroticismo también bajo (21%) no te tambaleas a nivel emocional ni en una negociación de un contrato ni en un reclamo. Esta combinación es el perfil de “venta de una asociación de largo plazo” que maximiza el valor de vida del cliente (LTV).',
    s: [
      'Maximizar la lealtad del cliente: con una amabilidad alta, formas una relación en la que el cliente no es un simple comprador, sino un “socio”. Te conviertes en el responsable de ventas con la tasa más alta de renovación y de recomendación (referral).',
      'Una gestión sistemática del cliente: con una responsabilidad alta, rastreas y gestionas con minucia la fecha de renovación de un contrato, el cambio de un responsable clave y el historial de un reclamo. Una gestión anticipada, de cuidar al cliente antes de que lo diga, es la base de la confianza.',
      'La resiliencia relacional en un reclamo: con un neuroticismo bajo y una amabilidad alta, aunque aparezca un reclamo o una queja, lo resuelves sin dañar la relación. La percepción de “si está este responsable, se puede confiar” convierte una crisis, al contrario, en una oportunidad de reforzar la confianza.'
    ],
    g: [
      'Complementar la captación de un cliente nuevo: si te concentras en la gestión de los clientes actuales, puede quedar corta la apertura de un mercado nuevo. Si sistematizas la petición de una presentación de un cliente actual (un programa de referidos), puedes ampliar de forma natural un cliente nuevo sobre la base de tu relación.',
      'Explorar una técnica nueva de ventas: con una apertura baja, si solo usas la forma actual de venta relacional, puedes quedarte atrás en un entorno digital de ventas. Prueba, una a una, una forma nueva, como la venta en redes o el marketing de contenido.'
    ],
    t: [T('HubSpot AI', 'main', 'La gestión sistemática de la relación con el cliente y del pipeline', 'HubSpot AI automatiza tu gestión sistemática del cliente, de una responsabilidad alta. La IA rastrea, por cliente, el historial de interacción, la fecha de renovación de un contrato, el cambio de un responsable, y te envía un aviso. Un aviso del tipo “hace 30 días que no contactas con este cliente” protege una relación valiosa.', 'HubSpot AI, analiza las 30 empresas a mi cargo y dime en cuáles hay una señal de riesgo de cancelación (una bajada reciente de la interacción, un aumento de reclamos, una fecha de renovación del contrato cercana). En cada una, recomienda también la acción inmediata de restauración de la relación.'),
        T('Claude', 'specialist', 'Una comunicación difícil con un cliente y una estrategia de restauración de la relación', 'Claude te ayuda, a ti de una amabilidad alta, a resolver un problema, en una comunicación difícil, sin dañar la relación. Si preparas con Claude una comunicación que al cliente le puede resultar incómoda —un escrito de trámite de un reclamo, el aviso de una subida de precio, la guía de un cambio de condición de un contrato—, sale la mejor expresión.', 'Claude, escribe el correo de aviso, a una empresa cliente con la que llevamos 3 años de trato, de que el año que viene hay que subir un 10% la tarifa del servicio. Explica con claridad la razón de la subida (un aumento del costo, una mejora del servicio) y, a la vez, incluye el agradecimiento por la asociación de largo plazo y la voluntad de seguir colaborando.'),
        T('Notion AI', 'specialist', 'La gestión de la relación con un cliente VIP y de un programa de referidos', 'Notion AI gestiona de forma sistemática tu relación con un cliente clave. Si acumulas en Notion, por cliente VIP, el historial de comunicación, la información del responsable, una nota particular y el estado de un referido, la IA rastrea incluso “a quién presentó este cliente y de qué forma se le transmitió el agradecimiento”.', 'Notion AI, analiza el estado de referidos de mis 10 clientes VIP. Ordena, en cada uno, el número de clientes nuevos que presentó, el número de conversiones a contrato y las ventas totales de su aporte, y propone una idea de un programa de agradecimiento para activar los referidos.')],
    syn: 'Tú, con una responsabilidad, una extraversión y una amabilidad todas altas, eres el mejor activo de las ventas: el que crea una relación en la que el cliente se queda. Si rastreas la relación con HubSpot AI, preparas una comunicación difícil con Claude y gestionas a un cliente VIP con Notion AI, te conviertes en el especialista de ventas de confianza que más clientes de largo plazo tiene en el sector.',
    day: '08:30 Revisas con HubSpot AI la lista de clientes a los que cuidar hoy. 09:30 Contacto regular de check-in con un cliente VIP. 11:00 Preparas con Claude una comunicación difícil y llevas una reunión. 13:30 Actualizas con Notion AI el estado de la relación con un cliente VIP. 15:00 Petición de un referido de un lead nuevo y un contacto de agradecimiento por una presentación. 16:30 Registras con HubSpot AI la actividad de hoy. 17:30 Preparación de una reunión importante con un cliente, mañana.'
  });
  add('01111', 'El manual vivo de las ventas, el sabio del retail', 'Gemini', ['RetailNext', 'Loom'], {
    i: 'Eres el criterio vivo del mundo del retail. La combinación de una apertura baja y una responsabilidad alta, una extraversión y una amabilidad altas, y un neuroticismo alto produce al especialista en ventas que cumple el manual a la perfección, en quien confía todo el equipo y que no pierde el centro ni en un reclamo difícil. Aunque tu capacidad de aceptar una tendencia nueva sea baja, la base es tan sólida que eres el pilar del equipo, que no se tambalea ni en una recesión. La combinación de una responsabilidad y una amabilidad altas produce al especialista ideal en ventas que cumple a la perfección el manual de atención al cliente y, a la vez, es de verdad amable con cada persona. Eres “la marca de certificación humana” con la que, solo con que estés, sube la categoría de la tienda. Un neuroticismo alto te hace sentir con fuerza la responsabilidad por el resultado del equipo y por la satisfacción del cliente. Esa responsabilidad es el motor que mantiene un criterio perfecto de servicio, pero a veces puede convertirse en una carga excesiva. Tu forma de gestionar de forma integrada, con Gemini, el resultado de todas las sucursales, de analizar con RetailNext el comportamiento del cliente en la tienda y de hacer más eficiente la formación del equipo con Loom, sube el estándar de la operación de retail.',
    s: [
      'Una especialidad equilibrada que cumple a la perfección el manual de atención al cliente y, a la vez, con una amabilidad cálida, ofrece la mejor experiencia de servicio.',
      'Un liderazgo de gestión de una crisis que, incluso en un reclamo difícil o en una situación complicada con un cliente, sostiene el centro del equipo y lleva la respuesta en la dirección correcta.',
      'Una consistencia que, con una base sólida y una responsabilidad constante, mantiene un resultado estable también en una recesión y se convierte en la base de confianza de todo el equipo.'
    ],
    g: [
      'Como un neuroticismo alto puede convertirse en una responsabilidad excesiva por el resultado del equipo y por la satisfacción del cliente, y provocar un agotamiento, practica definir con claridad el alcance de la responsabilidad y delegar la autoridad de forma adecuada.',
      'Como una apertura baja puede hacerte sentir resistencia ante la introducción de una forma nueva de vender, apoya un intento de innovación del equipo y crea un entorno en el que el criterio actual y una forma nueva puedan convivir.'
    ],
    t: [T('Gemini', 'main', 'Gestiona de forma integrada, con Google Workspace, el resultado, el inventario y la agenda de todas las sucursales', 'Integrado con Google Workspace, gestiona de forma unificada el resultado, el inventario y la agenda de todas las sucursales. Captas de un vistazo el estado de operación de varias tiendas y coordinas con eficiencia la comunicación de todo el equipo.', 'Con los datos de Google Workspace, resume el resultado de anoche y la agenda de hoy de todas las sucursales, y dime qué sucursal o qué persona del equipo necesita un apoyo prioritario hoy.'),
        T('RetailNext', 'specialist', 'Analiza el recorrido y el patrón de permanencia del cliente, y encuentra el punto de mejora del servicio', 'Analiza el recorrido del cliente en la tienda y el patrón de permanencia, y captura el punto de mejora de la calidad del servicio. Con una mejora de la operación de la tienda basada en datos, pules todavía con más precisión un criterio de servicio que ya es alto.', 'Analiza el recorrido y el patrón de permanencia de los clientes de esta mañana y señala 3 puntos concretos en los que se pueda subir todavía más la calidad del servicio esta tarde.'),
        T('Loom', 'specialist', 'Graba y comparte, en un video, un caso excelente de atención y el contenido de una formación del equipo', 'Graba en un video un caso excelente de atención al cliente y el contenido de una formación del equipo, y lo compartes. Al transmitir en un video tu criterio excepcional de servicio, subes de forma sistemática el nivel de servicio de todo el equipo.', 'Arma el guion de un video corto de Loom, para la formación de un nuevo, a partir de este caso excelente de atención de hoy, de modo que se pueda compartir con todo el equipo.')],
    syn: 'El socio con el que más sinergia tienes es un compañero de perfil innovador, que acepta con iniciativa una tendencia y una tecnología nuevas de ventas. Si tu base estable y su intento de innovación se equilibran, todo el equipo reúne tradición e innovación. Graba con Loom un caso excelente de tu atención y úsalo en la formación de un nuevo, y sistematiza el conocimiento para que tú te conviertas en el material vivo de formación del equipo.',
    day: 'A las 7:30 de la mañana, revisas en conjunto, con Gemini, el resultado de anoche y la agenda de hoy de todas las sucursales. Identificas una sucursal o una persona del equipo que hoy necesita un apoyo prioritario. A las 8:00, en el briefing del equipo, antes de abrir la tienda, compartes el punto central de servicio de hoy. Tomas como referencia el video de un caso excelente que preparaste con Loom. Desde las 9:00 empiezas la atención al cliente. Un reclamo difícil lo tramitas tú en persona y das el ejemplo al equipo. Después del almuerzo, revisas con los datos de RetailNext el patrón de comportamiento del cliente de la mañana y captas el punto de mejora del servicio de la tarde. Por la tarde das coaching a la atención de un compañero y grabas con Loom un caso excelente. Antes de irte, ordenas con Gemini el resultado de todo el día y preparas el hallazgo que vas a compartir mañana con el equipo.'
  });
  add('10000', 'El marketer genio y sensible: el incisivo de la estrategia de ventas', 'Grok', ['Elicit', 'Grammarly'], {
    i: 'Eres el genio disidente del sector del retail. La combinación de una apertura alta y una responsabilidad baja, una extraversión y una amabilidad bajas, y un neuroticismo bajo produce al estratega de marketing único que, con una sociabilidad casi nula, pero con una capacidad de otra dimensión de leer la psicología del consumidor, genera ventas. Todo recorrido y toda exhibición de la tienda te parecen ineficientes, y solo tú puedes explicar la razón. La combinación de una apertura alta y un neuroticismo bajo te permite sumergirte por completo en un tema que te interesa, no tambalearte ante una evaluación externa y desarrollar un hallazgo original. La promoción que diseñaste no se parece a ninguna forma anterior y, aun así, el resultado arma un récord sorprendente de ventas. Una amabilidad baja se convierte en un obstáculo para ejecutar tu idea dentro del equipo. Un hallazgo de genio, si la organización no lo ejecuta, no produce un resultado. La rutina de explorar a fondo, con Grok, la psicología del consumidor, de analizar una investigación de marketing con Elicit y de transmitir la idea de forma convincente con Grammarly, ayuda a que tu hallazgo original se vuelva realidad.',
    s: [
      'Una capacidad de hallazgo que, al analizar el mecanismo de fondo de la psicología de compra del consumidor, diseña una estrategia original de ventas que va más allá de una forma habitual de vender.',
      'Una convicción y una capacidad independiente de ejecución que, sin tambalearte ante una evaluación externa, si juzgas que tu análisis es correcto, lo empujas hasta el final.',
      'Una concentración que, al sumergirte por completo en un tema que te interesa, produce un hallazgo de profundidad de primer nivel del sector.'
    ],
    g: [
      'Como una amabilidad y una extraversión bajas te dificultan persuadir a la organización de una idea, toma el hábito de proponerla en un documento claro y convincente, escrito con Grammarly.',
      'Como una responsabilidad baja puede impedir que una idea brillante se conecte con la ejecución, convierte en una regla el adjuntar, a toda idea, un plan simple de ejecución de 3 etapas.'
    ],
    t: [T('Grok', 'main', 'Explora con mirada crítica la investigación y la tendencia más recientes de la psicología del consumidor', 'Explora con mirada crítica la investigación y la tendencia más recientes sobre la psicología del consumidor y el comportamiento de compra. Dudas de la lógica dominante de marketing, la contradices con datos y desarrollas tu propia teoría original de la psicología del consumidor.', 'Encuentra, con una mirada crítica, la investigación y la tendencia más recientes sobre la psicología de compra del consumidor que contradigan la lógica dominante de marketing, y ayúdame a desarrollar una hipótesis original que pueda aplicar a la exhibición de nuestra tienda.'),
        T('Elicit', 'specialist', 'Busca y analiza, con IA, un artículo académico sobre comportamiento del consumidor, psicología del precio y efecto de una exhibición', 'Busca y analiza, con IA, un artículo académico sobre el comportamiento del consumidor, la psicología del precio y el efecto de una exhibición. Respaldas tu hallazgo de marketing con un fundamento académico y subes el poder de persuasión dentro de la organización.', 'Busca artículos académicos sobre el efecto de una exhibición y la psicología del precio que respalden esta hipótesis de marketing, y resume el fundamento que puedo usar para persuadir al equipo.'),
        T('Grammarly', 'specialist', 'Ordena una idea compleja de marketing en un documento claro que la dirección pueda entender', 'Ordena una idea compleja de marketing y el resultado de un análisis en un documento claro que la dirección pueda entender. Bajas la barrera del lenguaje para que tu hallazgo original sea aceptado en la organización.', 'Convierte este hallazgo de marketing en una propuesta breve y clara para la dirección, con un plan de ejecución de 3 etapas, de modo que se entienda sin una jerga innecesaria.')],
    syn: 'El socio con el que más sinergia tienes es un gerente extravertido de marketing, que ejecuta la idea en el terreno y lleva al equipo. Con la división de roles en la que tú analizas y diseñas, y ellos ejecutan, tu hallazgo de genio produce un resultado en la realidad. Una vez al trimestre, presenta al equipo un hallazgo nuevo de la psicología del consumidor, visibiliza tu especialidad y ve acumulando confianza dentro de la organización.',
    day: 'A las 8:00, empiezas el día explorando con Grok la investigación y el caso más recientes relacionados con el comportamiento del consumidor. Un hallazgo interesante lo anotas de inmediato. De 9:00 a 11:00 es el horario central de análisis. Exploras con Elicit un artículo académico relacionado y extraes un hallazgo aplicable a la operación actual de la tienda. A las 11:00, ordenas el resultado del análisis, con Grammarly, en una propuesta breve. Incluyes un plan de ejecución de 3 etapas. Después del almuerzo, revisas los datos del estado de la tienda, los comparas con el resultado del análisis y verificas el hallazgo. Por la tarde desarrollas una idea nueva de una promoción de psicología del consumidor y planificas una prueba piloto de pequeña escala. Antes de irte, ordenas en Notion el hallazgo principal de hoy.'
  });
  add('10001', 'El investigador independiente del mercado, el cerebro recluso de las ventas', 'Perplexity', ['Consensus', 'GitHub Copilot'], {
    i: 'Eres el investigador solitario del mundo de las ventas. La combinación de una apertura alta y una responsabilidad baja, una extraversión y una amabilidad bajas, y un neuroticismo alto produce al analista independiente del mercado que explora a fondo, tú solo, y construye tu propia filosofía de ventas. Te gusta más investigar una tendencia de análisis de una zona comercial que una cena del equipo, y, en el tema de mercado que te enganchó, presumes un conocimiento de nivel de experto. Una apertura alta te da una curiosidad intelectual fuerte por un mercado nuevo y por una tendencia del consumidor. El entregable de tu análisis de mercado, a menudo, se convierte en una innovación que cambia la dirección de ventas de la empresa. Esta capacidad callada de innovar es tu competitividad central. Un neuroticismo alto crea inquietud por la exactitud del resultado de un análisis y, junto con una responsabilidad baja, provoca un conflicto sobre el grado de acabado. Tu forma de hacer una investigación profunda del mercado con Perplexity, de asegurar un fundamento académico con Consensus y de automatizar el análisis de datos con GitHub Copilot, sube la profundidad de una investigación independiente de ventas.',
    s: [
      'Una capacidad independiente de exploración que cuestiona la forma dominante de vender y, con un análisis propio del mercado, descubre una oportunidad nueva de ventas y un enfoque distinto.',
      'Una especialidad concentrada que, en el área de mercado en la que te concentras, acumula un conocimiento y un hallazgo de una profundidad que supera a un experto.',
      'Una capacidad de hallazgo que, con base en datos y en una investigación, presenta una alternativa convincente sobre la dirección de las ventas e influye en la toma de decisiones de la organización.'
    ],
    g: [
      'Como un neuroticismo alto puede dejarte poca confianza en el resultado de un análisis y hacerte dudar a la hora de compartirlo, convierte en rutina el pedir retroalimentación a un colega cuando el grado de acabado está en un 70%.',
      'Como una responsabilidad y una extraversión bajas hacen que, a veces, no transmitas el resultado de una investigación a la organización y te lo quedes tú solo, arma una rutina regular de, una vez al mes, briefar al equipo un hallazgo del mercado.'
    ],
    t: [T('Perplexity', 'main', 'Explora a fondo, con un fundamento académico, un dato global de distribución y una tendencia del consumidor', 'Explora a fondo, junto con un fundamento académico, un dato global de distribución, una investigación de una tendencia del consumidor y la información de un mercado emergente. A tu pregunta de profundidad le ofrece el dato de la fuente más confiable.', 'Explora, con fuentes confiables y un fundamento académico, el dato global de distribución y la tendencia del consumidor más recientes sobre este mercado emergente, y resume lo que podría cambiar la dirección de ventas de nuestra empresa.'),
        T('Consensus', 'specialist', 'Busca una investigación académica sobre comportamiento del consumidor, estrategia de precios y eficacia de una venta', 'Busca una investigación académica relacionada con el comportamiento del consumidor, una estrategia de precios y la eficacia de una venta. Respaldas tu filosofía de ventas y la dirección de un análisis con una investigación académica, y subes el poder de persuasión dentro de la organización.', 'Encuentra investigación académica sobre la eficacia de esta estrategia de precios y del comportamiento del consumidor, y arma el fundamento que puedo usar para proponerle a la dirección un cambio de la estrategia de ventas.'),
        T('GitHub Copilot', 'specialist', 'Escribe un script de automatización para reunir y analizar datos del mercado', 'Escribe un script de automatización de la recolección y el análisis de datos del mercado. Al automatizar una recolección y un procesamiento repetidos de datos, inviertes más tiempo en el análisis real y en extraer un hallazgo.', 'Arma un script que recoja y limpie, de forma periódica, estos datos del mercado, y que deje listo un resumen para el análisis, de modo que yo pueda concentrarme en extraer el hallazgo.')],
    syn: 'El socio con el que más sinergia tienes es un gerente de ventas con capacidad de ejecución, que lleva el resultado de un análisis al terreno. Cuando tu análisis profundo del mercado se encuentra con su capacidad de ejecución, se arma la estrategia de ventas más potente. Cuando, sobre la base de la investigación que construiste con Consensus y Perplexity, le propones a la dirección un cambio de la estrategia de ventas, tu investigación solitaria se convierte en la influencia más callada y más potente, la que cambia la dirección de la empresa.',
    day: 'A las 7:00 de la mañana, revisas con Perplexity los datos globales del mercado y la tendencia de distribución actualizados anoche. De 8:00 a 11:00 es el horario central de investigación. Exploras con Consensus un artículo académico relacionado y ejecutas con GitHub Copilot el script de análisis de datos. A las 11:00 escribes un resumen intermedio del resultado de la investigación. Aunque no esté terminado, anotas el avance. Después del almuerzo, complementas con Perplexity un ítem que pide una investigación adicional. A las 14:00 compartes en el canal del equipo una frase con el hallazgo del mercado de hoy. Minimizas la comunicación, pero mantienes la visibilidad. Por la tarde te concentras en escribir el informe de análisis y en fijar la dirección de la investigación de la semana que viene.'
  });
  add('10010', 'El vendedor romántico, el filósofo de la relación', 'Claude', ['Suno AI', 'MindOS'], {
    i: 'Eres el filósofo romántico del mundo de las ventas. La combinación de una apertura alta y una responsabilidad baja, una extraversión baja, una amabilidad alta y un neuroticismo bajo produce al vendedor artístico que no vende un objeto, sino un recuerdo y una experiencia. Tu forma de, en un té con el cliente, buscar un valor más allá del negocio, y de cuidar la relación en sí, crea una confianza profunda, más que un resultado rápido. La combinación de una amabilidad y una apertura altas te da la capacidad de entender a fondo, y de empatizar con, el sueño y el deseo del cliente. Lo que propones no es la especificación de un producto, sino la experiencia que el cliente va a disfrutar a través de él. Este enfoque emotivo crea una lealtad del cliente difícil de explicar solo con la razón. Gracias a un neuroticismo bajo, no te tambaleas ante un rechazo o un fracaso, y cultivas la relación desde una perspectiva de largo plazo. Tu forma de convertir, con Claude, una idea emotiva de ventas en una propuesta de negocio elegante, de crear con Suno AI un contexto creativo de ventas y de armar con MindOS un flujo de trabajo personalizado de ventas, eleva la venta a un arte.',
    s: [
      'Una capacidad de venta emotiva que no vende la función de un producto, sino la emoción y la historia que el cliente va a experimentar, y lleva la decisión de compra más por la emoción que por la razón.',
      'Una paciencia que invierte más en una relación de largo plazo que en un resultado de corto plazo y, incluso ante un rechazo, no se rinde y va acumulando confianza con el cliente.',
      'Un pensamiento innovador que explora sin parar una colaboración nueva y una forma creativa de vender, e intenta un enfoque diferenciado que un competidor no había pensado.'
    ],
    g: [
      'Como una responsabilidad baja puede llevar a omitir una tarea administrativa de ventas, fíjate el principio de “primero el trabajo, después el romanticismo”: un presupuesto y un documento de un contrato se tramitan de inmediato.',
      'Como un enfoque emotivo puede no funcionar con todos los clientes, prepara también un repertorio de ventas basado en hechos, para un cliente que prioriza los datos y la lógica.'
    ],
    t: [T('Claude', 'main', 'Convierte una idea emotiva de ventas y la historia de un cliente en una propuesta elegante de negocio', 'Convierte una idea emotiva de ventas y la historia de un cliente en una propuesta elegante de negocio y en un guion de ventas. Tu ocurrencia romántica queda expresada en un lenguaje profesional de negocio y se comunica a clientes diversos.', 'Convierte esta idea emotiva y la historia del cliente en una propuesta breve de negocio y en un guion de ventas, que suene profesional y, a la vez, conserve la emoción de la experiencia que el cliente va a vivir.'),
        T('Suno AI', 'specialist', 'Genera la música de ambiente que encaja con una reunión o un evento de ventas', 'Genera la música de ambiente que encaja con una reunión con un cliente o con un evento de ventas. Le sumas un ambiente emotivo particular al encuentro con el cliente y creas una experiencia original de ventas, que expresa la filosofía de la marca en música.', 'Genera una pieza breve de ambiente, cálida y elegante, para una reunión de esta tarde con un cliente, que exprese la filosofía de nuestra marca y acompañe una conversación sobre la experiencia, no sobre la especificación.'),
        T('MindOS', 'specialist', 'Arma un asistente personalizado de ventas de IA, con información y un guion a la medida de cada cliente', 'Arma un asistente personalizado de ventas de IA, y gestiona información a la medida de cada cliente y un guion de ventas. Le delegas a la IA la tarea administrativa repetida de ventas y tú te concentras en una relación creativa de ventas.', 'A partir de las notas de la reunión de hoy con este cliente, actualiza en MindOS su perfil y prepárame un guion personalizado y los 3 puntos de seguimiento para el próximo contacto.')],
    syn: 'El socio con el que más sinergia tienes es un colega de perfil analítico, fuerte en una gestión sistemática de las ventas y en el análisis de datos. La colaboración es natural: tú acumulas una relación emotiva con el cliente, y ellos la sistematizan con datos. Arma la rutina de registrar en MindOS una conversación particular y un hallazgo que compartiste con un cliente, para personalizar todavía más el siguiente contacto, y envía con regularidad, con Claude, un mensaje de agradecimiento, para mantener la relación de forma continua.',
    day: 'A las 8:00, revisas con MindOS el rasgo del cliente con el que vas a comunicar hoy y el contenido de la conversación anterior. Preparas un enfoque personalizado para cada uno. A las 9:00, escribes con Claude el correo de agradecimiento y el mensaje de seguimiento que vas a enviar hoy. Le sumas una expresión emotiva que lleva tu sinceridad. A media mañana llevas la reunión con un cliente clave. Antes que del producto, conversas primero sobre el sueño y el objetivo del cliente. En el almuerzo, preparas con Suno AI la música que encaja con el ambiente de la reunión de la tarde. Por la tarde exploras una idea nueva de una colaboración y profundizas la relación con un cliente actual. Antes de irte, registras en MindOS la conversación con todos los clientes que viste hoy y preparas con Claude el mensaje de seguimiento de mañana.'
  });
  add('10011', 'Quien se gana el corazón del cliente: el sabio de la sala de atención', 'Claude', ['Intercom', 'Wysa'], {
    i: 'Eres el sanador emotivo del mundo de las ventas. La combinación de una apertura alta y una responsabilidad baja, una extraversión baja, una amabilidad alta y un neuroticismo alto produce al especialista en ventas de perfil de atención, que entiende a fondo el corazón del cliente y construye confianza con una empatía de verdad. No sientes el verdadero sentido en vender un objeto, sino en el rol de socio que resuelve, junto con el cliente, su problema. La combinación de una amabilidad y una apertura altas te da la capacidad de descubrir la necesidad real, escondida detrás de una petición de superficie. Tu sensibilidad de poder escuchar lo que el cliente no dijo te lleva a proponer una solución diferenciada de la de un competidor. Esta atención de profundidad va más allá de una compra simple y se conecta con una relación de largo plazo. Un neuroticismo alto te hace susceptible, a nivel emocional, a la actitud agresiva de un cliente difícil o a una petición injusta. La rutina de preparar con Claude una comunicación auténtica ante una situación difícil con un cliente, de sistematizar el trabajo de atención con Intercom y de gestionar el agotamiento emocional con Wysa, mantiene de forma sostenible tu capacidad de empatía.',
    s: [
      'Una capacidad profunda de empatía que capta la necesidad y la emoción reales, escondidas en las palabras del cliente, y propone una solución a la medida, que va más allá de una petición de superficie.',
      'Una capacidad de venta basada en la relación que, con un cliente cuya confianza ya ganaste, mantienes una lealtad de largo plazo y se conecta con una recompra y una recomendación.',
      'Una capacidad de armonizar que, incluso en una situación difícil con un cliente, mantiene el centro emocional y encuentra una solución con la que ambas partes quedan satisfechas.'
    ],
    g: [
      'Como un neuroticismo alto te lleva a herirte a nivel emocional ante el ataque de un cliente difícil, define con claridad un límite emocional y cultiva la conciencia de separar la empatía del agotamiento emocional.',
      'Como una responsabilidad baja puede hacer que se descuide la gestión de un documento y de un registro de ventas, arma una rutina de una nota rápida: en los 3 minutos posteriores a una reunión, registras solo lo esencial.'
    ],
    t: [T('Claude', 'main', 'Escribe un texto de respuesta empático y auténtico ante una situación difícil con un cliente', 'Escribe un texto de respuesta empático y auténtico ante una situación difícil con un cliente. Te ayuda a que, en una carta de agradecimiento, una disculpa o una comunicación de una situación sensible, tu sinceridad se transmita sin un malentendido.', 'Escribe una respuesta empática y auténtica a esta situación difícil con un cliente. Que se reconozca su emoción, que no haya un malentendido y que se proponga una vía de resolución con la que ambas partes puedan quedar satisfechas.'),
        T('Intercom', 'specialist', 'Gestiona de forma integrada el historial de atención y el canal de comunicación con el cliente', 'Gestiona de forma integrada el historial de atención al cliente y el canal de comunicación. Al registrar, por cliente, el contenido de una atención y una preferencia, ofreces en el siguiente contacto una experiencia consistente y personalizada, y mantienes la relación con un seguimiento automático.', 'A partir del historial de atención de este cliente en Intercom, prepárame un resumen de su preferencia y un mensaje de seguimiento personalizado para el próximo contacto.'),
        T('Wysa', 'specialist', 'Previene el agotamiento emocional y recupera la energía para la siguiente atención', 'Previene el agotamiento emocional y el burnout. Reconoces la fatiga emocional que se acumula después de una atención difícil, ordenas la emoción con un coaching de IA y recuperas la energía para la siguiente atención.', 'Acabo de terminar una atención difícil y se me acumuló fatiga emocional. Guía una revisión breve para separar la empatía del agotamiento y recuperar energía antes de la siguiente conversación.')],
    syn: 'El socio con el que más sinergia tienes es un colega de perfil analítico, fuerte en la gestión de datos de ventas y de un proceso. La colaboración en la que tú construyes una relación profunda con el cliente, y ellos la sistematizan con datos, va acumulando de forma continua el activo de ventas del equipo. Después de vivir una situación difícil con un cliente, lo central de la sostenibilidad de largo plazo es compartirlo con honestidad con un colega y pedir apoyo.',
    day: 'A las 8:00, revisas en Intercom el registro anterior de los clientes con una atención prevista hoy. Preparas un enfoque personalizado para cada uno. A las 9:00, practicas con Claude el texto de respuesta de un escenario complejo de atención de hoy. Terminas la preparación emocional ante una situación difícil. Desde media mañana empiezan las atenciones. Después de cada una, registras de forma breve en Intercom lo esencial. En el almuerzo, revisas y ordenas con Wysa la fatiga emocional acumulada en las atenciones de la mañana. Te recargas 5 minutos antes de retomar las de la tarde. Por la tarde, escribes con Claude la comunicación de seguimiento de un cliente clave y la envías. Antes de irte, registras de forma breve lo que aprendiste en las atenciones de hoy y lo que vas a mejorar mañana.'
  });
  add('10100', 'El vendedor libre que, ante un rechazo, sigue intentando un método nuevo', 'ChatGPT', ['Lavender', 'Notion AI'], {
    i: 'Cuando el cliente dice “lo voy a pensar”, tú pasas de inmediato al siguiente ángulo: “¡ah, claro! Entonces déjeme mostrarle esta parte una vez más.” La combinación de una ocurrencia creativa de un 73% de apertura, un 71% de extraversión y un neuroticismo bajo (20%) es, en el área de ventas, la del “vendedor libre que no se rinde ante un rechazo y sigue intentando un método nuevo”. Con una responsabilidad baja (25%) respondes de forma improvisada, a la altura de la situación, más que con un guion fijo de ventas, y con una amabilidad baja (22%) confías más en tu propio juicio que en la reacción del cliente. Este estilo libre de vender produce un contrato incluso en un cliente inesperado.',
    s: [
      'Tolerancia al rechazo y un intento continuo: con un neuroticismo bajo, un fracaso de un contrato o un rechazo no te golpea, y pasas de inmediato al siguiente intento. La tenacidad de, aunque te rechacen 100 veces, hacer la propuesta 101 es, en las ventas, el activo más potente.',
      'Una venta que se adapta a la situación: con una responsabilidad baja, haces una venta flexible que responde de inmediato a la reacción del cliente, más que a una presentación fija. Aunque el cliente lleve la conversación en una dirección inesperada, lo sigues de forma improvisada y encuentras la oportunidad.',
      'Una propuesta creativa de un paquete: con una apertura alta, combinas de una forma nueva el producto o el servicio, a la altura de la necesidad del cliente. La capacidad de armar en el momento un paquete o una condición que antes no existían es la que lleva el contrato.'
    ],
    g: [
      'Sistematizar el seguimiento: con una responsabilidad baja, la medida de después de una reunión puede ser lenta o escaparse. Si conviertes en una regla el “enviar un correo de resumen dentro de las 24 horas posteriores al cierre de una reunión”, la impresión mejora de forma visible.',
      'Invertir en una relación de largo plazo: con una amabilidad baja, el mantenimiento de la relación de después de un contrato se puede descuidar. El hábito de un contacto breve en el aniversario del contrato o en el cumpleaños del cliente sube la tasa de renovación.'
    ],
    t: [T('ChatGPT', 'main', 'El generador rápido de una propuesta que apoya una venta improvisada', 'ChatGPT te ofrece un apoyo inmediato a tu estilo improvisado de vender. Cuando, en medio de una reunión, el cliente dice una necesidad inesperada, con la excusa de ir un momento al baño puedes preparar en 5 minutos, con ChatGPT, “el ángulo de una propuesta a la medida de esta necesidad del cliente”.', 'ChatGPT, el cliente de un startup de salud con el que me reuní hoy dijo que “el problema no es el costo, sino la preocupación de que, después de adoptarlo, el equipo no se adapte”. Dime 3 ángulos de una propuesta para disolver esa inquietud, y una forma de subrayar la fortaleza de apoyo al onboarding de nuestra solución.'),
        T('Lavender', 'specialist', 'La optimización automática, a la medida del cliente, de un correo de ventas', 'Lavender es la herramienta que, con IA, sube la tasa de respuesta del correo de ventas que envías. Cuando escribes un correo, Lavender te da en tiempo real una retroalimentación del tipo “esta frase se ve como spam” o “si cambias el asunto así, sube la tasa de respuesta”. A ti, que por una responsabilidad baja la calidad del correo no te queda pareja, Lavender te ayuda a mantener una calidad consistente.', 'Lavender, optimiza el siguiente correo para subir la tasa de respuesta. En el asunto y en el cuerpo, dime el punto de mejora de cada uno y propone una versión corregida. [pegar el borrador del correo]'),
        T('Notion AI', 'specialist', 'El seguimiento de la actividad de ventas y la automatización de la gestión posterior', 'Notion AI automatiza la “gestión de después de una reunión”, lo que más se te escapa a ti, de una responsabilidad baja. Si registras de forma breve el contenido de una reunión, la IA genera en automático el calendario de follow-up y la siguiente acción.', 'Notion AI, ordena el estado del pipeline de ventas de este mes. Muestra el número de clientes y la tasa de conversión por etapa (lead-contacto-propuesta-negociación-contrato) y recomiéndame los 5 clientes en los que debo concentrarme ahora mismo.')],
    syn: 'Tu energía creativa y sin reserva de ventas es la fuerza que abre un mercado nuevo. Si apoyas una venta improvisada con ChatGPT, subes la calidad del correo con Lavender y sistematizas el seguimiento con Notion AI, tu forma libre de vender se conecta con un resultado estable.',
    day: '09:00 Revisas con Notion AI la lista de follow-up de hoy. 09:30 Preparas con ChatGPT el escenario de la reunión de hoy. 10:30 Concentración en reuniones con clientes (outreach de la mañana). 13:30 Optimizas con Lavender el correo que vas a enviar hoy. 14:30 Captación y contacto de un lead nuevo. 16:00 Registras con Notion AI el contenido de la reunión de hoy y cargas el calendario de seguimiento. 17:30 Preparas con ChatGPT la estrategia de la reunión de mañana.'
  });
  add('10101', 'El vendedor de energía, quien más contactos nuevos genera', 'ChatGPT', ['HubSpot AI', 'Notion AI'], {
    i: 'Eres tú quien, en un stand de una feria, intercambia tarjetas con 100 personas en 3 horas y vuelve eufórico diciendo “¡hoy parece que voy a poder agendar una reunión!”. Con una ocurrencia creativa de ventas de un 74% de apertura y una comunicación animada de un 73% de extraversión, eres, en el área de ventas, el “vendedor de energía” que más contactos de clientes nuevos genera. Con una responsabilidad baja (26%) descubres un lead, pero el seguimiento es débil, y con un neuroticismo alto (71%) recibes un estrés intenso ante la presión de alcanzar un objetivo o ante el fracaso de un contrato. Estructurar esta energía es el núcleo del resultado.',
    s: [
      'El campeón de la captación de un cliente nuevo: con una apertura y una extraversión altas, descubres un cliente potencial nuevo en cualquier parte. Eres la fuente del pipeline del equipo, la que más leads nuevos produce, en canales diversos: una conferencia, redes, una presentación.',
      'Un enfoque creativo de ventas: sin atarte a una forma actual de vender, propones de forma creativa un ángulo nuevo de una propuesta, la composición de un paquete, un servicio de prueba. Eres de quienes arman una propuesta ante la que el cliente dice “esta forma no la había visto”.',
      'La energía de la comunicación con el cliente: con una extraversión alta, en todo punto de contacto con el cliente transmites una energía positiva. Eres la persona más rápida en crear una buena impresión en la primera reunión y en abrir la puerta de una relación.'
    ],
    g: [
      'Arma un sistema de gestión de leads: si no gestionas de forma sistemática el lead que descubriste, se queda en “una recolección de tarjetas”. El hábito de rastrear el estado de todos los leads con un CRM o con Notion AI convierte la energía de captación en un contrato real.',
      'La gestión del estrés: con un neuroticismo alto, lo pasas extremadamente mal cuando falla un contrato o no se alcanza un objetivo. Si reformulas cada rechazo como “este cliente todavía no está listo” y registras, por semana, en qué avanzaste, previenes el agotamiento.'
    ],
    t: [T('ChatGPT', 'main', 'Una propuesta creativa de ventas y un análisis rápido del cliente', 'ChatGPT convierte con rapidez tu idea creativa de ventas en una propuesta real. Cuando se te ocurre un segmento nuevo de cliente o un enfoque de ventas, verifícalo y concrétalo con ChatGPT. Empieza con una pregunta del tipo “¿tendría efecto este enfoque de propuesta, con este sector como objetivo?”.', 'ChatGPT, arma una secuencia de correos en frío para desarrollar un cliente nuevo de una empresa de servicios de IT. En la forma de un 1.er correo (despertar el interés), un 2.º a los 3 días (propuesta de valor) y un 3.º a la semana (compartir un caso), cada uno de no más de 300 caracteres. Que no se vea como spam y que despierte el interés.'),
        T('HubSpot AI', 'specialist', 'La gestión de leads y la automatización del pipeline de ventas', 'HubSpot AI rastrea y gestiona de forma sistemática los muchos leads que descubriste. A ti, que por una responsabilidad baja el seguimiento de un lead es débil, HubSpot te envía en automático un aviso del tipo “ahora tienes que contactar con este lead”. Cuando se encuentran la energía de la captación y un sistema de gestión, la tasa de conversión a contrato sube de golpe.', 'HubSpot AI, analiza los 50 leads nuevos que descubrí este mes y saca los 10 de mayor posibilidad de conversión. Puntúalos según el sector, el tamaño, la relevancia con nuestro producto y la interacción reciente.'),
        T('Notion AI', 'specialist', 'El registro de la actividad de ventas y la gestión del estrés', 'Notion AI rastrea la actividad de ventas de alguien como tú, de una responsabilidad baja, y, al mostrarte cada semana en qué avanzaste, suaviza la inquietud que viene de un neuroticismo alto. Si registras el cliente al que contactaste hoy, la reunión que avanzó y la propuesta que enviaste, baja la inquietud de “¿qué hice hoy?”.', 'Notion AI, en el registro de mi actividad de ventas del trimestre anterior, analiza el rasgo común de los clientes que se convirtieron en un contrato. Ordena el sector, el tamaño, el método del primer contacto, el plazo hasta el contrato y el punto decisivo de persuasión.')],
    syn: 'Tú, cuya fortaleza es una ocurrencia creativa y una energía animada, eres la fuente más importante del pipeline de ventas. Si armas una propuesta creativa con ChatGPT, gestionas los leads de forma sistemática con HubSpot AI y registras la actividad con Notion AI, tu energía se convierte en un resultado estable de ventas.',
    day: '09:00 Revisas con HubSpot AI la lista de leads de follow-up de hoy. 09:30 Preparas con ChatGPT el mensaje a la medida del cliente al que vas a contactar hoy. 10:30 Contacto y reuniones con clientes (outreach concentrado). 13:30 Actividad de captación de un lead nuevo (redes, petición de una presentación, networking). 15:30 Actualizas en HubSpot el registro de la actividad de hoy. 16:30 Analizas con ChatGPT un caso de rechazo de hoy y revisas el punto de mejora. 17:30 Actualizas con Notion AI el estado de la actividad de la semana.'
  });
  add('10110', 'Las ideas explotan, el archivo no: la celebridad de la tienda', 'ChatGPT', ['Beautiful.ai', 'Calendly'], {
    i: 'Eres la estrella animadora de la tienda. La combinación de una apertura alta y una responsabilidad baja, una extraversión y una amabilidad altas, y un neuroticismo bajo produce a la celebridad de la tienda, de quien explotan las ideas. Frente al mostrador, haces reír a los clientes con una frase ingeniosa y tienes el atractivo natural de, en 5 minutos, hacerte amigo incluso de alguien que acabas de ver. La combinación de una extraversión y una amabilidad altas te convierte, en cualquier parte, en quien levanta el ambiente. Dentro del equipo insuflas ánimo y, para el cliente, haces que comprar sea una experiencia alegre. Si a tu estrella se le suma un sistema, el ascenso a gerente de sucursal es cuestión de tiempo. Una responsabilidad baja es el mayor desafío. Las ideas ingeniosas de ventas brotan, pero el documento del cierre de un resultado siempre es un trabajo de última hora. La rutina de sistematizar con ChatGPT una idea suelta, de armar con Beautiful.ai un documento de planeación convincente y de gestionar con eficiencia, con Calendly, una agenda ajetreada, le suma capacidad administrativa a tu estrella.',
    s: [
      'Una energía innata de estrella de ventas que, en cualquier rincón de la tienda, atrae la mirada del cliente y, con una comunicación natural, crea un ambiente de compra.',
      'Un liderazgo de ideas que, al lanzar sin parar una idea nueva de ventas y la planeación de un evento, lleva la actividad creativa de ventas de todo el equipo.',
      'Una capacidad de, con una resiliencia optimista que, ante cualquier fracaso, te sacudes el polvo enseguida y vuelves a intentarlo con una actitud positiva, mantener de forma continua el ambiente del equipo en un tono positivo.'
    ],
    g: [
      'Como una responsabilidad baja puede atrasar un documento de ventas y el cierre de un resultado, fija los 30 minutos del cierre de cada día como “horario administrativo” y conviértelo en una regla que jamás se transige.',
      'Como, de convivir con tanta gente, a veces se te descarga la propia energía, una vez a la semana, asegúrate de forma consciente un tiempo de recarga solo para ti.'
    ],
    t: [T('ChatGPT', 'main', 'Ordena una idea suelta de ventas en un documento de planeación y en el plan de un evento, sistemáticos', 'Ordena una idea suelta de ventas en un documento de planeación sistemático y en el plan de un evento. Conviertes con rapidez una idea que lanzaste de forma improvisada en una estrategia de ventas ejecutable, y bajas la barrera de la ejecución.', 'Convierte esta idea improvisada de un evento de la tienda en un documento de planeación ejecutable: objetivo, cronograma, materiales, responsable y una forma de medirlo, listos para llevar al terreno esta semana.'),
        T('Beautiful.ai', 'specialist', 'Produce de forma profesional el documento de planeación de un evento de ventas y el informe de un resultado, para la dirección', 'Produce de forma profesional el documento de planeación de un evento de ventas y el informe de un resultado que le vas a proponer a la dirección. Al expresar tu idea creativa de forma visual y convincente, recibes el apoyo de la organización.', 'Pasa este plan de un evento de ventas a una presentación visual, convincente, de 8 diapositivas, para proponerle a la dirección el apoyo y el presupuesto.'),
        T('Calendly', 'specialist', 'Gestiona con eficiencia una agenda ajetreada de reuniones y de eventos', 'Gestiona con eficiencia una agenda ajetreada de varias reuniones y eventos. Con una coordinación automática de la agenda, no se te escapa una cita importante y, de antemano, también aseguras en el calendario el horario de trámite administrativo.', 'Configura mi Calendly de modo que, cada día, los 30 minutos anteriores al cierre queden bloqueados como horario administrativo, y que las reuniones y los eventos no se superpongan con esa franja.')],
    syn: 'El socio con el que más sinergia tienes es un colega responsable, fuerte en una ejecución y una gestión sistemáticas. La división de roles en la que tú aportas una idea creativa y una energía de ventas, y ellos la ejecutan de forma planificada, arma el mejor equipo. Ordena cada trimestre, con Beautiful.ai, una idea creativa de ventas, compártela con el equipo y consolida tu posición como el innovador de las ventas que recibe el apoyo de la dirección.',
    day: 'A las 8:00, concretas en 5 minutos, con ChatGPT, la idea de ventas de hoy. Conviertes con rapidez una idea improvisada en una forma ejecutable. A las 9:00, revisas con Calendly la agenda de hoy. Compruebas que el horario administrativo de 30 minutos antes del cierre esté asegurado en el calendario. A media mañana te concentras, en la tienda, en una comunicación natural con el cliente y en una venta de un evento. Después del almuerzo, actualizas con Beautiful.ai el documento de planeación del evento de ventas de este mes. Vas terminando, de forma gradual, el material de una propuesta para la dirección. Por la tarde llevas el ambiente del equipo y el impulso de ventas de la tarde. 30 minutos antes del cierre, terminas el cierre del resultado de hoy y el trámite de un documento. Solo ese horario no se transige, ante ninguna tentación.'
  });
  add('10111', 'Un rechazo es el comienzo de un contrato: el vendedor bulldozer', 'ChatGPT', ['Castmagic', 'Canva Magic'], {
    i: 'Eres el explorador bulldozer del terreno de las ventas. La combinación de una apertura alta y una responsabilidad baja, una extraversión y una amabilidad altas, y un neuroticismo alto produce al vendedor impetuoso que, aunque lo rechacen diez veces, hace el undécimo intento. No es que no temas un rechazo: tienes tu propio marco de reinterpretarlo como el comienzo de un contrato. La combinación de una extraversión y una amabilidad altas te da la capacidad sorprendente de entablar amistad de inmediato con alguien que acabas de conocer. En una llamada en frío o en una visita sin cita, tu energía natural y tu sinceridad derriban la barrera de defensa del cliente. Esta capacidad de formar una relación inicial es tu mayor competitividad. Un neuroticismo alto hace que, incluso en medio de una actividad animada, se te acumulen por dentro la tensión y el estrés. Tu forma de concretar con ChatGPT una idea improvisada de ventas, de registrar con eficiencia la actividad de ventas con Castmagic y de producir en el momento, con Canva Magic, un material de ventas, le suma una estructura estratégica a una energía impetuosa de ventas. Una responsabilidad baja puede hacer que se descuide el seguimiento de después de una venta. La mayor pérdida de una oportunidad es que una buena impresión creada en el primer contacto no se conecte con un contrato, por la ausencia de un follow-up.',
    s: [
      'Una energía innata de ventas y una afinidad que, en cualquier situación, te acercan de forma natural al cliente y forman de inmediato una cercanía.',
      'Una resiliencia que interpreta un rechazo, de forma positiva, como una parte del proceso de un contrato, no se rinde ante un fracaso y sigue intentándolo de forma continua.',
      'Una capacidad creativa de ocurrencia de ventas que, de forma improvisada, arma un enfoque nuevo de ventas y una idea de captación de un cliente.'
    ],
    g: [
      'Como una responsabilidad baja puede hacer que se descuide el follow-up de una venta y que se caiga un contrato que estaba a punto de cerrarse, arma un sistema de seguimiento automático dentro de las 24 horas posteriores a una reunión.',
      'Como un neuroticismo alto puede crear una inquietud excesiva por el resultado, frente al volumen de actividad, toma el hábito de rastrear por separado un indicador de actividad (número de reuniones, número de propuestas enviadas) y un indicador de resultado.'
    ],
    t: [T('ChatGPT', 'main', 'Convierte una idea improvisada de ventas en una propuesta estructurada y en un guion a la medida del cliente', 'Convierte una idea improvisada de ventas en una propuesta estructurada y en un guion de respuesta a la medida del cliente. Generas con rapidez una estrategia distinta de comunicación, por tipo de cliente, y le sumas un fundamento estratégico a una venta impetuosa.', 'Arma 2 o 3 guiones de acercamiento, estructurados, para el tipo de cliente al que voy a contactar hoy, y una propuesta breve a su medida, que le sume un fundamento estratégico a una primera conversación en frío.'),
        T('Castmagic', 'specialist', 'Registra en automático una llamada y una reunión de ventas, y extrae lo esencial', 'Registra en automático una llamada y una reunión de ventas, y extrae lo esencial. Conservas para que no desaparezca del registro el hallazgo del cliente que obtuviste en el terreno, y ordenas en automático el contenido concreto que vas a usar en el seguimiento.', 'A partir de la transcripción de la reunión de ventas de hace un momento, extrae lo esencial, el hallazgo del cliente y los 3 puntos concretos que debo usar en el follow-up de las próximas 24 horas.'),
        T('Canva Magic', 'specialist', 'Produce con rapidez, en el terreno, un material de presentación del producto, una propuesta a la medida y una presentación de ventas', 'Produce con rapidez, en el terreno y en el momento, un material de presentación del producto, una propuesta a la medida y una presentación de ventas que le vas a mostrar al cliente. Incluso sin una preparación previa, armas de inmediato un material profesional de ventas y subes la confianza del cliente.', 'Arma, en 10 minutos, un material visual breve de presentación del producto y una propuesta a la medida de este cliente, listo para mostrárselo en la reunión de esta tarde.')],
    syn: 'El socio con el que más sinergia tienes es un responsable de apoyo a las ventas, de perfil analítico, fuerte en una gestión sistemática del CRM y en el seguimiento. La división de roles es ideal: tú descubres un cliente nuevo y formas la relación inicial, y ellos gestionan los datos y ejecutan el follow-up de forma sistemática. Convierte en una regla absoluta el registrar de inmediato, después de cada reunión de ventas, lo esencial con Castmagic, y el automatizar el follow-up dentro de las 24 horas.',
    day: 'A las 8:00, preparas con ChatGPT 2 o 3 guiones de acercamiento que encajan con el tipo de cliente objetivo de ventas de hoy. Desde las 9:00 empiezas la actividad. Te concentras en la captación de un cliente nuevo y en un outreach en frío. Justo después de cada reunión, registras de inmediato lo esencial con Castmagic. A media mañana, avanzas el seguimiento enviándole a un cliente potencial el material a la medida que armaste con Canva Magic. Después del almuerzo, revisas el resultado de las ventas de la mañana y ajustas la prioridad de la tarde. Con ChatGPT, exploras un enfoque nuevo ante una situación difícil con un cliente que surgió en la mañana. Por la tarde te concentras en una reunión de profundidad con un cliente de alta posibilidad de un contrato. Antes de irte, confirmas si quedó listo el follow-up de todas las reuniones de hoy.'
  });
  add('11000', 'El especialista estratégico en ventas que construye confianza con datos', 'ChatGPT', ['Claude', 'Notion AI'], {
    i: 'En el momento en que el responsable de una empresa cliente dice “el competidor nos bajó el precio”, tú ya estás sacando los datos: “en el último año, nuestra tasa de cumplimiento del plazo de entrega fue del 99,3% y los reclamos de calidad, cero. Si solo se mira el precio, este es el valor que se deja pasar.” Con un pensamiento estratégico de un 75% de apertura y una capacidad minuciosa de preparación de un 79% de responsabilidad, eres, en el área de ventas y de gestión de clientes, “el especialista estratégico en ventas que construye confianza con datos”. Con una extraversión baja (21%) prefieres una relación profunda, de uno a uno, más que una red amplia, y con una amabilidad también baja (20%) eliges la prueba lógica de valor, más que una persuasión emocional.',
    s: [
      'Un poder de persuasión de ventas basado en datos: con una apertura alta, entiendes a fondo la estructura de negocio y la necesidad del cliente y, con la responsabilidad, terminas una propuesta que lo respalda con datos. Una venta que persuade con números, no con emoción, es la forma que más confianza genera.',
      'Una gestión estratégica de una relación de largo plazo con el cliente: con una extraversión baja, en lugar de gestionar a muchos clientes de forma superficial, analizas a fondo a un cliente clave y lo desarrollas como un socio estratégico de largo plazo. Tú captas primero el plan de negocio a 3 años del cliente y se lo propones.',
      'Armar una estrategia de diferenciación frente a un competidor: con una apertura alta, analizas la tendencia del mercado y el mapa competitivo y, con la responsabilidad, encuentras un punto concreto de diferenciación. Eres el estratega de ventas que lleva la competencia del precio al valor.'
    ],
    g: [
      'Ampliar la red: con una extraversión baja, la captación de un cliente nuevo puede resultarte difícil. Si gestionas de forma sistemática la presentación y la referencia de un cliente actual, puedes ampliar clientes también sin un networking extravertido.',
      'Complementar la conexión emocional: con una amabilidad baja, la relación con el cliente se puede endurecer en torno a la transacción. Una vez al trimestre, el tiempo que inviertes en una conversación fuera del negocio (cómo está, un interés) vuelve todavía más sólida una relación de largo plazo.'
    ],
    t: [T('ChatGPT', 'main', 'Una propuesta a la medida del cliente y la extracción de una estrategia de ventas', 'ChatGPT es el socio que vuelve todavía más potente tu venta basada en datos. Si le cargas el sector, el tamaño y el problema actual de la empresa cliente, ChatGPT extrae el punto de una propuesta de valor a su medida. Úsalo en la forma de “ordena, desde el ángulo del ROI, qué valor concreto puede darle nuestro producto a esta empresa”.', 'ChatGPT, una empresa mediana de manufactura, cliente nuestra, recibió una propuesta más barata de un competidor. Nuestro producto es un 15% más caro, pero nuestras fortalezas son una tasa de cumplimiento del plazo del 99%, una respuesta de posventa en menos de 4 horas y 3 años de garantía gratuita. Arma 5 argumentos para persuadir al cliente de que mire, en lugar de una comparación simple de precio, el costo total (TCO).'),
        T('Claude', 'specialist', 'El socio de una propuesta de profundidad y de un análisis del cliente', 'Claude es la IA que mejor encaja con tu estilo analítico de vender. Si le explicas una situación compleja del cliente, Claude extrae el hallazgo central y una estrategia a su medida. Es excepcional para escribir el borrador de una propuesta, un análisis de la competencia y el desarrollo de la lógica de respuesta a una objeción prevista del cliente.', 'Claude, mañana tengo la reunión de renovación del contrato anual con una empresa cliente clave (un distribuidor de 50.000 millones de wones de ventas al año). Los temas que previsiblemente va a plantear el cliente: una petición de bajada de precio, más flexibilidad en el plazo de entrega y la asignación de un responsable exclusivo. Prepara nuestra posición y el argumento de persuasión de cada tema. Distingue también lo que sí se puede ceder y lo que no.'),
        T('Notion AI', 'specialist', 'La gestión estratégica de la información del cliente y del pipeline de ventas', 'Notion AI gestiona de forma sistemática la información, el historial de conversación y el estado de un contrato de los clientes clave que tú gestionas. Es la herramienta óptima para tu forma, de una extraversión baja, de gestionar a fondo a un número reducido de clientes.', 'Notion AI, analiza el calendario de renovación de un contrato y el registro de temas de los últimos 3 meses de mis 15 empresas cliente clave. Saca las 3 de mayor riesgo de renovación (varios temas, una señal de bajada de la satisfacción) y, en cada una, recomienda la acción inmediata de mejora de la relación.')],
    syn: 'Tu venta estratégica, con una apertura y una responsabilidad altas, tiene como arma los datos y un análisis de profundidad. Si armas la estrategia con ChatGPT, terminas la propuesta con Claude y gestionas al cliente de forma sistemática con Notion AI, creces como el especialista en ventas B2B que más confianza genera.',
    day: '08:30 Revisión previa, con Notion AI, del cliente de la reunión de hoy. 09:30 Preparas con ChatGPT el argumento de una propuesta a la medida del cliente. 10:30 Reunión con el cliente. 13:30 Escribes con Claude el borrador de una propuesta. 15:30 Registras con Notion AI el contenido de la reunión y cargas la medida de seguimiento. 17:00 Preparas con ChatGPT la reunión de mañana. 17:30 Revisión del estado del pipeline de ventas.'
  });
  add('11001', 'El analista de retail obsesionado con los datos, el maestro recluso de los números', 'Perplexity', ['GitHub Copilot', 'RetailNext'], {
    i: 'Eres el maestro recluso de los datos del mundo del retail. La combinación de una apertura y una responsabilidad altas, una extraversión y una amabilidad bajas, y un neuroticismo alto produce al estratega de retail que, en un lugar que no se ve en el terreno de las ventas, hace girar el motor de análisis más potente. Te importa más la calidad de un informe de análisis de datos que una cena del equipo, y tu identidad es un perfeccionismo que no admite ni un error de 1 cm en una exhibición. La combinación de una apertura y una responsabilidad altas crea la capacidad poco común de explorar sin parar la tecnología más reciente de retail y una teoría del comportamiento del consumidor y, a la vez, de aplicarla a fondo en el trabajo real. El análisis de una zona comercial o la guía de una exhibición que tú diseñaste no es un simple informe: se convierte en una directriz de ejecución que cambia el terreno. Un neuroticismo alto puede desarrollarse como una obsesión con un análisis perfecto. A veces, de esperar a que el análisis quede perfecto, se te escapa el momento de ejecutar. La rutina de rastrear en tiempo real, con Perplexity, una tendencia de distribución, de implementar la automatización de un análisis con GitHub Copilot y de analizar con precisión, con RetailNext, los datos de la tienda, sube al mismo tiempo la velocidad y la exactitud del análisis.',
    s: [
      'Una capacidad de análisis predictivo que, al integrar la tendencia más reciente de distribución y los datos del comportamiento del consumidor, arma una estrategia de zona comercial y de exhibición un paso por delante de un competidor.',
      'Una capacidad perfeccionista de gestión que aplica un listón alto a cada detalle de la operación de la tienda y mantiene de forma sistemática la consistencia de la marca y la calidad del servicio.',
      'Una capacidad técnica de análisis que automatiza el procesamiento de datos de retail y extrae con rapidez el hallazgo central de una información vasta de la tienda.'
    ],
    g: [
      'Como un neuroticismo alto puede hacerte obsesionarte con el grado de acabado de un análisis y atrasar la ejecución, define con claridad el criterio de un “análisis suficientemente bueno” y arma la regla de, en ese punto, pasar a la ejecución.',
      'Como una extraversión y una amabilidad bajas pueden dificultarte persuadir al equipo de terreno del resultado de un análisis, desarrolla la técnica de contar una historia con los datos y logra la empatía del terreno.'
    ],
    t: [T('Perplexity', 'main', 'Explora, con datos de nivel académico, la tendencia más reciente de distribución y una investigación de la psicología de consumo', 'Explora, con datos de nivel académico, la tendencia más reciente de distribución, una investigación de la psicología de consumo y la estrategia de una marca competidora. Reúnes con rapidez, junto con una fuente exacta, información de profundidad sobre una zona comercial concreta o un segmento de consumidor.', 'Reúne, con fuentes exactas, la tendencia más reciente de distribución, una investigación de la psicología de consumo y la estrategia de un competidor aplicables a esta zona comercial, y resume lo que debería cambiar en nuestra estrategia de exhibición.'),
        T('GitHub Copilot', 'specialist', 'Desarrolla con eficiencia un script en Python de procesamiento de datos de retail, de predicción de ventas y de análisis de una zona comercial', 'Desarrolla con eficiencia un script en Python de procesamiento de datos de retail, de predicción de ventas y de análisis de una zona comercial. Con el apoyo de la IA para programar, automatizas un trabajo complejo de análisis de datos y acortas de forma radical el tiempo de análisis.', 'Arma un script en Python que limpie los datos de ventas de la tienda, prediga la tendencia de la semana que viene y deje listo un resumen de los hallazgos para el informe de la mañana.'),
        T('RetailNext', 'specialist', 'Captura, con un análisis de video de IA, el recorrido, el tiempo de permanencia y el patrón de contacto con un producto', 'Captura, con un análisis de video de IA, el recorrido de un visitante de la tienda, el tiempo de permanencia y el patrón de contacto con un producto. Sobre la base de los datos del comportamiento del cliente, extraes una vía de optimización de la exhibición y de mejora del diseño de la tienda.', 'Analiza el recorrido, el tiempo de permanencia y el patrón de contacto con un producto de ayer, y propón 3 cambios concretos de exhibición o de diseño de la tienda para aplicar esta semana.')],
    syn: 'El socio con el que más sinergia tienes es un gerente extravertido de la tienda, que ejecuta con energía tu análisis en el terreno. La división de roles es ideal: tú ofreces un análisis perfecto, y ellos llevan al equipo a ejecutarlo. Cuando compartas el resultado de un análisis, preséntalo como una historia completa que incluya no solo el “What (el estado)” y el “Why (la causa)”, sino también el “How (la vía de ejecución)”, para bajar la barrera de ejecución del equipo de terreno.',
    day: 'A las 7:00 de la mañana, captas en 15 minutos, con Perplexity, la noticia de distribución y la tendencia de un competidor actualizadas anoche. A las 8:00, analizas con el tablero de RetailNext los datos de comportamiento del cliente de la tienda de ayer. Si hay un patrón anómalo, lo anotas de inmediato. De 9:00 a 12:00 es el horario central de análisis. Desarrollas y ejecutas con GitHub Copilot un script de análisis de datos. Después del almuerzo, ordenas el resultado del análisis en un informe y escribes la guía de ejecución que le vas a transmitir al equipo de terreno. A las 15:00 llevas una reunión breve de actualización con el equipo de la tienda. Complementas con Perplexity un ítem que pide una investigación adicional. Antes de irte, fijas la dirección del análisis de mañana y, si hay un factor de inquietud, lo conviertes en un plan concreto de investigación.'
  });
  add('11010', 'El VMD de un sentido agudo, el artesano de la exhibición', 'Claude', ['Midjourney', 'Sleep Cycle'], {
    i: 'Eres el artista del visual merchandising (VMD) que convierte la tienda en una galería. La combinación de una apertura y una responsabilidad altas, una extraversión baja, una amabilidad alta y un neuroticismo bajo produce al visual merchandiser que le da un significado a cada detalle de una exhibición y diseña una experiencia de compra perfecta. La posición de los dedos de un maniquí, el ángulo de una luz, el flujo de color de la disposición de un producto: todo eso es, para ti, el lenguaje con el que diseñas la emoción del cliente. La combinación de una apertura y una amabilidad altas te da la capacidad de aceptar con rapidez una tendencia nueva y, a la vez, de entender a fondo la sensibilidad de un compañero del equipo y del cliente. El espacio de la tienda que tú armas no es un simple lugar de venta: se convierte en un espacio con una historia que el cliente quiere experimentar. La combinación de una extraversión baja y un neuroticismo bajo hace posible un trabajo creativo callado, pero estable. Tu rutina de pulir con Claude el concepto de la tienda y la estrategia de VMD, de explorar de forma visual, con Midjourney, una idea nueva de exhibición y de gestionar con Sleep Cycle la energía creativa, apoya un crecimiento continuo como especialista en VMD.',
    s: [
      'Un sentido de diseño del espacio que, al diseñar de forma integral la exhibición, la iluminación y el recorrido de la tienda, estimula de forma natural el deseo de compra del cliente.',
      'Una capacidad creativa de ejecución que integra una tendencia de temporada y la identidad de la marca, y realiza un visual de la tienda consistente y atractivo.',
      'Un sentido basado en datos que, con una observación minuciosa, capta el patrón de comportamiento del cliente dentro de la tienda y lo refleja en el VMD.'
    ],
    g: [
      'Como un listón alto de acabado del VMD puede dar una carga excesiva al equipo, practica un liderazgo que prioriza, más que un resultado perfecto, un proceso en el que participa todo el equipo.',
      'Como una extraversión baja puede hacerte poco proactivo a la hora de persuadir a la dirección de una idea de VMD, expresa con claridad el valor de negocio de la idea en un documento de planeación convincente, escrito con Claude.'
    ],
    t: [T('Claude', 'main', 'Escribe con sensibilidad y lógica un documento de concepto de la tienda, una guía de VMD y un informe de estrategia de exhibición de temporada', 'Escribe con sensibilidad y lógica un documento de planeación del concepto de la tienda, una guía de VMD y un informe de la estrategia de exhibición de una temporada. Conviertes una idea creativa en el lenguaje del negocio y logras el entendimiento y el apoyo de la dirección.', 'Convierte este concepto de VMD de la próxima temporada en un documento de planeación breve, sensible y lógico, que le deje claro a la dirección el valor de negocio y el efecto esperado en la experiencia de compra.'),
        T('Midjourney', 'specialist', 'Explora de forma visual un concepto nuevo de exhibición y una idea de diseño de la tienda', 'Explora de forma visual un concepto nuevo de exhibición y una idea de diseño de la tienda. Antes de implementarlo en la realidad, simulas con IA varios escenarios de VMD, decides la dirección óptima y la compartes con el equipo.', 'Genera 4 visualizaciones de un concepto de exhibición de la próxima temporada, con este paleta de color y este flujo de recorrido, para compararlas con el equipo antes de implementarlo en la tienda.'),
        T('Sleep Cycle', 'specialist', 'Gestiona el patrón óptimo de sueño que pide un trabajo creativo de VMD', 'Gestiona el patrón óptimo de sueño que hace falta para un trabajo creativo de VMD. Al analizar los datos del sueño, identificas la franja en la que la energía creativa es más alta y colocas en ese horario un trabajo importante de planeación de VMD.', 'A partir de mis datos de sueño de esta semana, dime en qué franja de la mañana suele estar más alta mi energía creativa, para colocar ahí la planeación de un VMD importante.')],
    syn: 'El socio con el que más sinergia tienes es un colega de perfil analítico, fuerte en los datos de compra del cliente y en el análisis de las ventas. Verifica tu intuición de VMD con su análisis de datos y arma un ciclo de retroalimentación que refleja el resultado del análisis en la siguiente planeación de VMD. Visualiza con Midjourney un concepto nuevo de VMD, compártelo en una reunión del equipo, recibe retroalimentación de puntos de vista diversos y desarrolla la idea.',
    day: 'A las 7:00, con el análisis del sueño de Sleep Cycle, captas el nivel de energía creativa de hoy. Un día de energía alta lo concentras en una planeación nueva de VMD; un día de energía baja, en la ejecución y en la colaboración con el equipo. A las 8:00, antes de abrir la tienda, inspeccionas en persona el estado del VMD. Corriges de inmediato una exhibición o una luz que se haya desalineado. A media mañana exploras con Midjourney el concepto de VMD de la temporada siguiente. Una idea interesante la conviertes, con Claude, en el borrador de un documento de planeación. Después del almuerzo, revisas los datos del recorrido del cliente en la tienda y evalúas el efecto del VMD. Un hallazgo nuevo lo reflejas en el siguiente VMD. Por la tarde revisas con el equipo el estado de ejecución del VMD y intercambias retroalimentación. Antes de irte, empiezas con Sleep Cycle la preparación de un sueño óptimo y anotas, de forma ligera, una idea para el trabajo creativo de mañana.'
  });
  add('11011', 'El poder silencioso, el maestro recluso de la gestión de un VIP', 'Perplexity', ['Notion AI', 'DeepL'], {
    i: 'Eres el maestro callado de la gestión de un cliente VIP. La combinación de una apertura y una responsabilidad altas, una extraversión baja, una amabilidad alta y un neuroticismo alto produce al caballero de las ventas que, sin hacer ruido, se gana a la perfección el corazón de un cliente VVIP. Sin alzar la voz y sin una actuación llamativa, construyes confianza registrando un aniversario mínimo y un gusto del cliente, y lanzando la propuesta perfecta en el momento óptimo. La combinación de una responsabilidad y una amabilidad altas produce al mejor vendedor relacional, que cumple sin falta cada promesa con el cliente y, en ese proceso, expresa un interés de verdad. El cliente se emociona al ver que lo recuerdas, y eso se conecta con un cliente leal de por vida. Un neuroticismo alto puede desarrollarse como la inquietud de no estar a la altura de la expectativa de un cliente importante. Tu forma de investigar a fondo, con Perplexity, la información de negocio del cliente, de gestionar a la perfección esa información con Notion AI y de apoyar la comunicación con un cliente global con DeepL, lleva la precisión de una venta VIP hasta el extremo.',
    s: [
      'Un sentido de venta centrado en la relación que, al entender a fondo el gusto y la situación de negocio de cada cliente VVIP, lanza la propuesta perfecta en el momento óptimo.',
      'Una capacidad minuciosa de gestión del cliente que registra y gestiona a la perfección toda la información y cada promesa, y hace que el cliente sienta que lo tratan de forma especial.',
      'Una capacidad constante de ejecución que, dentro del equipo, en silencio, registra la mayor satisfacción del cliente y el mayor aporte a las ventas, y hace de as silencioso de la organización.'
    ],
    g: [
      'Como un neuroticismo alto puede convertirse en la inquietud de no estar a la altura de la expectativa de un cliente importante, practica el valor de prepararte lo bastante de antemano y, aun así, ejecutar aunque no esté perfecto.',
      'Como una extraversión baja te lleva a concentrarte más en la gestión de un cliente actual que en la captación de uno nuevo, arma un programa de referidos que sistematice la llegada de un cliente nuevo a través de la recomendación de uno actual.'
    ],
    t: [T('Perplexity', 'main', 'Investiga a fondo la tendencia del sector, la noticia reciente de la empresa y el estado de un competidor de un cliente VIP', 'Investiga a fondo la tendencia del sector de negocio de un cliente VIP, la noticia reciente de su empresa y el estado de un competidor. Antes de una reunión, captas a la perfección el contexto de negocio del cliente, subes la pertinencia de la propuesta y lo impresionas.', 'Resume, con fuentes, la noticia más reciente de la empresa del cliente VIP con el que me reúno hoy, la tendencia de su sector y el movimiento de un competidor, y dame 3 hallazgos de valor que pueda compartir en la conversación.'),
        T('Notion AI', 'specialist', 'Gestiona de forma sistemática, por cliente, un aniversario, un gusto, el historial de compra y una nota de conversación', 'Gestiona de forma sistemática, por cliente, un aniversario, un gusto, el historial de una compra anterior y una nota de conversación. Con una búsqueda de IA, encuentras de inmediato la información del cliente que necesitas y, en toda comunicación, ofreces una experiencia personalizada.', 'Antes de la reunión de hoy, sácame de Notion el aniversario, el gusto, el historial de compra y la última nota de conversación de este cliente VIP, y dime qué detalle personalizado debo mencionar.'),
        T('DeepL', 'specialist', 'Traduce con exactitud y con categoría un correo, una propuesta y un contrato con un cliente VIP global', 'Traduce con exactitud y con categoría un correo, una propuesta y un contrato con un cliente VIP global. Con una comprensión del contexto superior a la de un traductor general, subes la profesionalidad y la sensación de confianza de la comunicación con el cliente.', 'Traduce este correo y esta propuesta para un cliente VIP en el extranjero, con un tono elegante y profesional, y revisa que el matiz de la relación de largo plazo no se pierda.')],
    syn: 'El socio con el que más sinergia tienes es un responsable de ventas extravertido, fuerte en la captación de un cliente nuevo y en formar una relación inicial. La división de roles en la que, cuando ellos descubren un cliente nuevo, tú lo desarrollas hacia una relación VIP de largo plazo, refuerza el portafolio de ventas de todo el equipo. Comparte con el equipo la información del cliente de Notion AI y arma un sistema para que, también cuando tú no estás, el cliente reciba una experiencia consistente.',
    day: 'A las 7:30, revisas en Notion AI la información del cliente VIP con el que tienes una comunicación prevista hoy. Confirmas un aniversario o un cambio reciente de negocio. A las 8:00, investigas con Perplexity la noticia más reciente y la tendencia del sector de la empresa del cliente con el que te reúnes hoy. Preparas un hallazgo de valor para compartir con él. A media mañana llevas la reunión con un cliente VIP. Justo después, registras de inmediato lo esencial en Notion AI. Después del almuerzo, escribes con DeepL un correo para un cliente VIP global y lo envías. Por la tarde te concentras en una investigación de profundidad y en la preparación de una propuesta para la siguiente reunión. Antes de irte, registras por completo en Notion AI el contenido de la comunicación con todos los clientes de hoy y fijas la siguiente acción.'
  });
  add('11100', 'Quien confronta al cliente con los hechos: el asesor de la lengua afilada', 'Grok', ['Grammarly', 'Otter.ai'], {
    i: 'Eres el inspector de la lógica del mundo de las ventas. La combinación de una apertura y una responsabilidad altas, una extraversión alta, una amabilidad baja y un neuroticismo bajo produce al especialista único en atención, que persuade al cliente con hechos y con lógica, no con emoción. Señalas con agudeza la lógica poco razonable de un cliente que duda, y demuestras con datos por qué tiene que comprar ahora. Una amabilidad baja hace que no mires el ánimo del cliente. El valor de decirle lo que necesita, más que lo que quiere oír: eso es el núcleo que te convierte, no en un simple vendedor, sino en un asesor de confianza. Muchas veces, el cliente que al principio se sintió incómodo con tu franqueza, más tarde se convierte en tu partidario más sólido. Gracias a un neuroticismo bajo, tienes una estabilidad que no se tambalea ni ante la presión de un resultado ni ante una oposición fuerte del cliente. Esta estabilidad psicológica vuelve todavía más potente tu poder de persuasión lógica. Tu forma de analizar con mirada crítica, con Grok, una tendencia del mercado, de terminar con Grammarly una propuesta convincente y de registrar una conversación de ventas con Otter.ai, maximiza la eficiencia de una venta basada en la lógica.',
    s: [
      'Una capacidad lógica de cierre que capta la razón real de una objeción, escondida detrás de un rechazo vago y de una duda del cliente, la contradice con datos y persuade.',
      'Una estabilidad psicológica que, ante la presión o la oposición de cualquier cliente, no se tambalea a nivel emocional y mantiene una lógica consistente.',
      'Una capacidad analítica de propuesta que, sobre la base de datos del mercado y de un análisis de la competencia, arma de forma convincente la razón objetiva por la que el cliente debe comprar.'
    ],
    g: [
      'Como una forma directa de comunicar, que viene de una amabilidad baja, a algunos clientes puede resultarles fría, toma el hábito de, antes de transmitir un hecho, expresar primero que entiendes la situación del cliente.',
      'Como, de perseguir una perfección lógica, se te puede escapar el momento del cierre, entrena el pasar, cuando el cliente envía una señal emocional positiva, de la lógica a una pregunta de cierre.'
    ],
    t: [T('Grok', 'main', 'Analiza con mirada crítica la tendencia del mercado y el estado de un competidor', 'Analiza con mirada crítica la tendencia del mercado y el estado de un competidor. Reúnes un fundamento objetivo de por qué la situación actual del cliente pide una decisión ahora, y aseguras el dato que vuelve todavía más aguda la lógica de la venta.', 'Analiza, con una mirada crítica, la tendencia más reciente del sector de la empresa del cliente con la que me reúno hoy y el movimiento de un competidor, y dame 3 datos objetivos para argumentar por qué tiene que decidir ahora.'),
        T('Grammarly', 'specialist', 'Pule de forma lógica y con un alto grado de acabado una propuesta de ventas, un correo y un documento de persuasión', 'Pule de forma lógica y con un alto grado de acabado una propuesta de ventas, un correo y un documento de persuasión. Subes la calidad para que tu forma directa de comunicar quede expresada, también en un documento, con claridad y profesionalidad.', 'Revisa esta propuesta y este correo de persuasión: que la lógica quede clara, que el tono sea profesional y que no suene más frío de lo necesario.'),
        T('Otter.ai', 'specialist', 'Registra en automático la conversación de una reunión de ventas y extrae lo esencial', 'Registra en automático la conversación de una reunión de ventas y extrae lo esencial. Al analizar la objeción que planteó el cliente y tu respuesta, mejoras de forma continua el guion lógico de ventas.', 'A partir de la transcripción de la reunión de ventas de hoy, extrae las objeciones del cliente y mi respuesta, y propón una lógica más sólida para el siguiente cierre.')],
    syn: 'El socio con el que más sinergia tienes es un responsable de ventas afable, hábil en formar una relación cálida. La división de roles en la que ellos construyen la confianza inicial con el cliente, y tú completas el cierre con una persuasión lógica, cubre todos los tipos de cliente. Cuando, en una reunión del equipo, compartas tu análisis agudo, presenta junto con la conclusión una propuesta ejecutable, y lidera de modo que la energía del equipo se use de forma constructiva.',
    day: 'A las 7:45 de la mañana, captas con Grok la tendencia más reciente del mercado del sector de la empresa del cliente de la reunión de hoy. Preparas 3 puntos de datos centrales para usarlos en la lógica de la venta. A las 9:00 empieza la primera reunión de ventas. Con Otter.ai registras la conversación en automático y te concentras en la objeción del cliente. A media mañana haces con Grammarly la revisión final del correo de una propuesta que vas a enviar hoy. Después del almuerzo, revisas el registro de Otter.ai y analizas, por cliente, la objeción central. Preparas una respuesta lógica todavía más sólida para cada una. En la reunión de ventas de la tarde, pones a prueba la lógica reforzada que preparaste en la mañana. Antes de irte, evalúas tú mismo el resultado de las ventas de hoy y la fuerza de la lógica, y fijas la dirección de mejora de mañana.'
  });
  add('11101', 'El líder de franquicia lleno de ambición, aspirante a CEO', 'Grok', ['AdCreative.ai', 'Beautiful.ai'], {
    i: 'Eres el estratega de franquicia que sueña con un imperio de distribución. La combinación de una apertura y una responsabilidad altas, una extraversión alta, una amabilidad baja y un neuroticismo alto produce al empresario ambicioso que, con una visión grande y audaz, ejecuta como un bulldozer. Te rebosa la energía de dibujar el panorama estratégico grande, desde la ampliación de sucursales en todo el país hasta el posicionamiento de la marca, y de llevarlo a la ejecución. Una amabilidad baja te lleva a priorizar el resultado más que la emoción. Eso a veces puede resultarles frío a los compañeros del equipo, pero hace posible fijar un objetivo claro y una evaluación justa. En una negociación con el dueño de una sucursal franquiciada, no te dejas llevar por la emoción de la otra parte y llevas la conclusión con la lógica del negocio. Un neuroticismo alto te da, al mismo tiempo, una inquietud fuerte por el resultado y un impulso. Tu forma de captar con Grok el punto débil de una franquicia competidora, de optimizar con AdCreative.ai un anuncio de captación de un franquiciado y de armar con Beautiful.ai un material estratégico que persuade a un inversionista y a un candidato a franquicia, sienta la base real de la construcción de un imperio de distribución.',
    s: [
      'Una visión estratégica y una capacidad de ejecución que dibujan el panorama grande de una estrategia de ampliación de la franquicia y, hasta el plan detallado de ejecución, lo armas de forma sistemática.',
      'Una capacidad de análisis del mercado que analiza con frialdad la fortaleza y el punto débil de una franquicia competidora, y capta una oportunidad de posicionamiento en el mercado.',
      'Un liderazgo de multitarea que impulsa al mismo tiempo varios encargos estratégicos, desde la captación de un dueño de sucursal hasta la construcción de la marca.'
    ],
    g: [
      'Como una amabilidad baja puede hacer que se descuide la gestión de una relación de largo plazo con el dueño de una sucursal, incluye como un horario imprescindible, cada trimestre, una captación de la satisfacción del franquiciado y una reunión de refuerzo de la relación.',
      'Como un neuroticismo alto puede convertirse en una obsesión excesiva con la velocidad de la ampliación, convierte en una regla de hierro el enfoque por etapas de, primero, estabilizar una sucursal cuya rentabilidad ya está asegurada y, después, avanzar a la siguiente ampliación.'
    ],
    t: [T('Grok', 'main', 'Analiza en tiempo real la condición de una franquicia competidora, su estrategia de marketing y la reacción del mercado', 'Analiza en tiempo real la condición de adhesión de una franquicia competidora, su estrategia de marketing y la reacción del mercado. Identificas una oportunidad de mercado que el competidor se saltó y el momento óptimo de una ampliación de franquicia, y construyes tu ventaja estratégica.', 'Analiza en tiempo real la condición de adhesión, la estrategia de marketing y la reacción del mercado de nuestras 3 franquicias competidoras principales, y señala una oportunidad de mercado que se hayan saltado y el mejor momento para ampliar.'),
        T('AdCreative.ai', 'specialist', 'Optimiza con IA un anuncio de captación de un franquiciado, un material de la marca y la promoción de una sucursal nueva', 'Optimiza con IA un anuncio de captación de un franquiciado, un material de marketing de la marca y un contenido de promoción de la apertura de una sucursal nueva. Generas y pruebas en automático el visual y la copia más convincentes para un candidato objetivo a franquicia.', 'Genera 5 variantes de un anuncio de captación de un franquiciado, con un visual y una copia que convenzan a un candidato objetivo, para probar cuál convierte mejor este mes.'),
        T('Beautiful.ai', 'specialist', 'Produce de forma profesional un material de IR para un inversionista, una presentación de una sesión informativa de franquicia y un informe de estrategia de la marca', 'Produce de forma profesional un material de IR para un inversionista, una presentación de una sesión informativa de franquicia y un informe de estrategia de la marca. Conviertes datos y una visión en una historia visual convincente, y persuades a un tomador de decisiones clave.', 'Arma una presentación de 12 diapositivas, para una sesión informativa de franquicia y un inversionista, que combine la visión de ampliación, la simulación de rentabilidad y el posicionamiento de la marca.')],
    syn: 'El socio con el que más sinergia tienes es un gerente minucioso de operación, fuerte en la operación real y en el apoyo a una sucursal franquiciada. La división de roles en la que tú diseñas la estrategia de ampliación, y ellos estabilizan la operación de una sucursal actual, crea un crecimiento sostenible. Comparte con todo el equipo, cada trimestre, una revisión estratégica con un material de Beautiful.ai, comunica con transparencia el estado de cumplimiento del objetivo y alinea la dirección del equipo.',
    day: 'A las 7:00 de la mañana, captas con Grok la tendencia de adhesión de un competidor y la noticia del mercado. Si aparece una oportunidad nueva de mercado, la anotas de inmediato. A las 9:00 preparas la reunión central de hoy, relacionada con la ampliación de la franquicia. Haces con Beautiful.ai la revisión final del material de una propuesta. A media mañana llevas la reunión con un candidato clave a franquicia. En la negociación, usas una simulación clara de rentabilidad, basada en datos. Después del almuerzo, revisas y optimizas con AdCreative.ai el material del anuncio de captación de un franquiciado de este mes. Por la tarde te concentras en el análisis de una zona comercial nueva y en la revisión del resultado de una sucursal actual. Antes de irte, ordenas el estado de avance de la ampliación de franquicia de hoy y fijas la prioridad de mañana.'
  });
  add('11110', 'El líder de satisfacción del cliente que lleva dentro un muñeco de la preocupación', 'Claude', ['Sprout Social', 'Headspace'], {
    i: 'Eres el líder devoto de ventas que, por la satisfacción del cliente, también se desvela de madrugada. La combinación de una apertura y una responsabilidad altas, una extraversión y una amabilidad altas, y un neuroticismo alto produce al gerente emotivo que se preocupa de verdad tanto por el equipo como por el cliente. Tienes una voluntad fuerte de armar un sistema perfecto de atención al cliente y, a la vez, la delicadeza de que incluso una queja mínima del cliente te mueve el ánimo. La combinación de una extraversión y una amabilidad altas te da la fortaleza de llevar el ambiente del equipo en un tono positivo y de construir una confianza cálida en la relación con el cliente. En el equipo en el que estás tú, se forma de manera natural una cultura sana de cuidarse y de apoyarse. Un neuroticismo alto es el desafío del liderazgo. Si reaccionas en exceso ante un error de un compañero o ante un reclamo de un cliente, puedes dañar la seguridad psicológica del equipo. La rutina de preparar con Claude una comunicación empática con el cliente, de monitorear con Sprout Social la reacción en línea y de mantener la estabilidad mental con Headspace, sube tu sostenibilidad como líder.',
    s: [
      'Una capacidad minuciosa de gestión del talento que capta la fortaleza de cada persona del equipo y lo lleva a desplegarla al máximo en la atención al cliente.',
      'Una capacidad perfeccionista de mejora del servicio que convierte una queja del cliente en una oportunidad de mejorar el sistema, y previene que se repita.',
      'Un liderazgo emotivo que, también en una crisis, mantiene la confianza con una comunicación empática y cálida, tanto con el equipo como con el cliente.'
    ],
    g: [
      'Como un neuroticismo alto puede convertirse en una preocupación excesiva incluso ante una queja menor del cliente, arma un sistema de triaje que clasifique una queja de forma objetiva y fije la prioridad.',
      'Como reaccionar con demasiada sensibilidad ante un error de un compañero puede dañar la seguridad psicológica, practica una forma de comunicar de liderazgo que reformule un error como una oportunidad de aprendizaje.'
    ],
    t: [T('Claude', 'main', 'Escribe con empatía y autenticidad una disculpa a un cliente enojado, un mensaje de coaching para el equipo y un informe a la dirección', 'Escribe con empatía y autenticidad una carta de disculpa a un cliente enojado, un mensaje de coaching para un compañero del equipo y un informe a la dirección. En una situación sensible, es el mejor socio para encontrar un lenguaje exacto y cálido.', 'Escribe una disculpa empática y auténtica a este cliente enojado, y un mensaje breve de coaching para el compañero del equipo que tramitó el caso, que reformule el error como una oportunidad de aprendizaje sin dañar la seguridad psicológica.'),
        T('Sprout Social', 'specialist', 'Monitorea en tiempo real la reacción en línea de un cliente sobre tu tienda o tu marca', 'Monitorea en tiempo real la reacción de un cliente, en línea, sobre tu tienda o tu marca. Captas con rapidez una reseña negativa o una publicación de una queja, respondes de forma anticipada y gestionas la reputación en línea.', 'Resume la reacción en línea de ayer sobre nuestra tienda o nuestra marca, señala una reseña o una queja negativa que pida una respuesta inmediata, y propone el tono de la primera respuesta.'),
        T('Headspace', 'specialist', 'Con 10 minutos de meditación al día, previene el agotamiento emocional como líder del equipo', 'Con 10 minutos de meditación al día, previene el agotamiento emocional como líder del equipo. Te ayuda a mantener la serenidad también en un día ajetreado, en el que se acumulan las quejas de un cliente, y les das al equipo, con el ejemplo, la importancia de cuidar la mente.', 'Guía una meditación de 10 minutos para empezar el día con serenidad, como líder de satisfacción del cliente, y otra de 5 minutos para cerrar la jornada sin llevarte la preocupación a casa.')],
    syn: 'El socio con el que más sinergia tienes es un colaborador de perfil analítico, que analiza un problema con base en datos, sin una alteración emocional. La colaboración en la que tú llevas el ambiente del equipo y la relación con el cliente, y ellos analizan los datos del servicio, arma el mejor equipo, con emoción y con lógica. En la reunión semanal del equipo, revisen juntos los datos de satisfacción del cliente, compartan la dirección de mejora con todo el equipo y aprovechen la inteligencia colectiva.',
    day: 'A las 7:00, revisas con Sprout Social la reacción en línea del cliente de ayer. Si hay una retroalimentación negativa, armas de inmediato un plan de respuesta. A las 8:00, con 10 minutos de meditación de Headspace, revisas tu estado emocional de hoy y te preparas la serenidad. A las 8:30, en la reunión diaria del equipo, compartes la dirección central de atención al cliente de hoy. Usas los puntos de comunicación principales que preparaste con Claude. A media mañana monitoreas la atención de un compañero y, si hace falta, das coaching. Escribes con Claude el borrador de la respuesta a un reclamo complejo. Después del almuerzo, revisas los datos de satisfacción del cliente de la mañana y fijas el punto central de la tarde. Por la tarde llevas tú en persona la comunicación de mantenimiento de la relación con un cliente VIP clave. Antes de irte, cierras el día con una sesión de 5 minutos de Headspace y ordenas el apoyo que el equipo va a necesitar mañana.'
  });
  add('11111', 'El dios de las ventas, el top sales al que mira el sector', 'Gemini', ['Salesforce Einstein', 'HeyGen'], {
    i: 'Eres la leyenda viva del mundo de las ventas. La combinación, en su valor más alto, de apertura, responsabilidad, extraversión, amabilidad y neuroticismo todos altos produce al top salesman que capta en un instante la psicología del cliente y, en el momento perfecto, lanza la mejor propuesta. El atrevimiento de abrir un mercado nuevo y la afinidad de, en 10 minutos, poner de tu lado a un cliente que acabas de conocer son tu arma central. Un neuroticismo alto es, para ti, un desafío. Una energía que rebosa y una sensibilidad exaltada a veces también se conectan con un agotamiento. Tienes una resiliencia excepcional de, aunque te rechacen, sacudirte el polvo de inmediato, pero, por dentro, se acumula la tensión por la presión de un resultado y por la expectativa del cliente. Reconocer eso y gestionarlo es la llave de una carrera de largo plazo en las ventas. Tu forma digital de vender —captar en tiempo real, con Gemini, la tendencia más reciente de negocio del cliente y usarla en la estrategia de ventas, analizar con Salesforce Einstein el patrón de compra, y producir con HeyGen un video personalizado de ventas— crea una experiencia del cliente de una dimensión completamente distinta a la de un competidor. Tu verdadero potencial no es simplemente vender mucho, sino convertirte en el socio estratégico que, junto con el cliente, arma el éxito de su negocio. Esta venta centrada en la relación te convierte, no en el rey de una venta de una sola vez, sino en una leyenda del sector.',
    s: [
      'Una afinidad innata que, incluso con un cliente que acabas de conocer, forma de inmediato confianza y cercanía, y acorta de forma radical el ciclo de una venta.',
      'La capacidad de, con el atrevimiento de abrir sin miedo un mercado y un segmento de cliente nuevos, y con un enfoque creativo, adelantarte en un área en la que no hay un competidor.',
      'Un sentido intuitivo de ventas que detecta un cambio sutil de la emoción del cliente y una señal de compra, y lanza, en el momento exacto, la propuesta óptima.'
    ],
    g: [
      'Como un neuroticismo alto puede conectarse con la presión de un resultado y con un agotamiento, incluye de forma obligatoria, en la agenda de ventas, una rutina semanal de gestión de la energía y un descanso intencional.',
      'Como el deseo de atraer a todos los clientes puede dispersar una energía valiosa, practica la estrategia de elegir y concentrarte: define un segmento central de cliente y concéntrate ahí.'
    ],
    t: [T('Gemini', 'main', 'Recibe en tiempo real, antes de una reunión, un briefing de la noticia más reciente, el estado financiero y la tendencia del sector de la empresa del cliente', 'Antes de una reunión de ventas, recibe en tiempo real un briefing de la noticia más reciente, el estado financiero y la tendencia del sector de la empresa del cliente. Integrado con Google Calendar, planificas el recorrido óptimo de ventas y, después de una reunión, se genera en automático la medida de seguimiento.', 'Antes de la reunión de hoy, brieféame en tiempo real la noticia más reciente, el estado financiero y la tendencia del sector de la empresa del cliente, y dame 3 temas de conversación y el recorrido óptimo del día, integrado con el calendario.'),
        T('Salesforce Einstein', 'specialist', 'Predice con IA el patrón de compra, una señal de riesgo de salida y una oportunidad de venta adicional', 'Predice con IA el patrón de compra del cliente, una señal de riesgo de salida y una oportunidad de upselling. Recibes, con base en datos, la recomendación del momento óptimo de contacto y del contenido de una propuesta, por cliente, y maximizas la eficiencia de las ventas.', 'En el tablero de Einstein, dime la prioridad de los clientes de hoy, el momento óptimo de contacto, una señal de riesgo de salida y una oportunidad de venta adicional, y recomienda el contenido de la propuesta de cada uno.'),
        T('HeyGen', 'specialist', 'Produce a gran escala un video de presentación de ventas, personalizado con el nombre del cliente y el de su empresa', 'Produce a gran escala un video de presentación de ventas, personalizado con el nombre del cliente y el de su empresa. Con un video personalizado en el que un avatar de IA habla como tú, subes de forma radical la tasa de respuesta de un outreach en frío que empieza en frío.', 'Arma el guion de 2 o 3 videos cortos de un avatar, personalizados con el nombre del cliente y el de su empresa, para un outreach en frío a un cliente potencial nuevo, que suban la tasa de respuesta.')],
    syn: 'El socio con el que más sinergia tienes es un planificador introvertido de ventas, fuerte en el análisis de datos y en el apoyo a las ventas. La división de roles en la que, mientras tú brillas frente al cliente, ellos apoyan el análisis y la preparación de una propuesta, sube de forma explosiva el resultado de todo el equipo. Por dentro, toma el hábito de registrar de inmediato en Salesforce la información del cliente y un hallazgo de ventas, para que tu experiencia se convierta en un activo de todo el equipo.',
    day: 'A las 7:00, recibes con Gemini el briefing de la noticia más reciente y del estado de negocio de la empresa del cliente con la que te reúnes hoy. Anotas 3 temas de conversación relacionados con el cliente. A las 8:30, revisas con el tablero de Salesforce Einstein la prioridad de los clientes clave de hoy. Sobre la base del momento de contacto que recomendó la IA, terminas el plan diario de ventas. De 9:00 a 12:00 es el horario de reuniones centrales de ventas, el que más concentración pide. En los 5 minutos posteriores a una reunión, registras en Salesforce lo esencial y la siguiente acción. Después del almuerzo, produces con HeyGen 2 o 3 videos personalizados de ventas para un cliente potencial nuevo. Por la tarde llevas una reunión de seguimiento y un cierre. Por la noche, te separas de forma intencional, por completo, de las ventas, y recargas energía. Una vez a la semana, el viernes por la noche, miras atrás el resultado de esta semana y armas la estrategia de la que viene.'
  });
})();

